// Hand-written chapters for players without a storyteller model.
// test/adventures.test.ts checks every entry's shape, lengths, and placeholders.
export const adventures = [
  {"id": "bell-that-forgot-morning", "style": "mystery", "title": "The Bell That Forgot Morning", "hook": "Find the stolen dawn before the village forgets how to begin.", "twist": "The supposed thief may be protecting the dawn from someone else.", "open": "The morning bell over {village} has gone silent. Three roads leave Mosswood; somewhere along them, someone is keeping the dawn.", "steps": ["Near {place} you find a bell clapper wrapped carefully in {wrap}, as if someone meant to keep it warm.", "{helper} admits nobody has been sure when to start the day; the bakers are guessing the hour by the smell of bread.", "Tiny footprints lead from the bell tower to {landmark}, and they are circling it, not running away.", "A shadow there points somewhere it shouldn’t: toward a hollow tree full of borrowed candles.", "Inside the hollow, a sleepy {bird} is sitting on {glow}.", "The {bird} explains it only wanted one more hour of quiet before the day came rushing in."], "end": "You and the {bird} agree on a gentler bell, rung a little later and a little softer. Morning returns to {village}, yawning, right on time.", "vars": {"wrap": ["moss", "a wool scarf", "a nest of pine needles", "a knitted tea cozy"], "bird": ["lark", "wren", "robin", "thrush"], "glow": ["a small, glowing egg of morning light", "a jar of bottled sunrise", "a warm, pearly ball of dawn"]}},
  {"id": "r-stranded-weather-sprite", "style": "rescue", "title": "The Sprite Who Missed Her Cloud", "hook": "A tiny weather sprite is stuck on a sunny rock while her cloud drifts away without her.", "twist": "The cloud didn’t leave her behind; it went looking for her and got lost too.", "open": "A weather sprite no bigger than a thimble sits on a Starfall Isle, drizzling sadly on one patch of moss. Her cloud left at dawn, and she can’t fly without it.", "steps": ["Near {place} you find a trail of damp stepping stones, each one holding a tiny puddle shaped like {puddle_shape}.", "The sprite tells you her cloud loves the smell of {scent} and always hums when it is happy.", "{helper} mentions a cloud that keeps circling {mill}, raining on the sails and humming.", "At {mill}, the sails are turning backward, pushing the cloud away each time it drifts close.", "You find the brake lever jammed with an empty bird’s nest and gently move the nest to a safer beam.", "The sails slow, the air stills, and a lonely cloud drifts nearer, humming louder with every gust."], "end": "You splash the stones with your waterskin, and the smell of {scent} draws the cloud down to the sprite. She hops aboard, and a soft thank-you drizzle follows you home under {weather}.", "vars": {"puddle_shape": ["a raindrop", "a tiny teacup", "a crescent moon", "a snail shell"], "scent": ["rain on warm stone", "rain on sun-baked slate", "rain on hot cobbles"], "mill": ["the old windmill", "the creaky windmill", "the hilltop windmill"]}},
  {"id": "r-lighthouse-keepers-cat", "style": "rescue", "title": "The Keeper’s Cat and the Low-Tide Caves", "hook": "A lighthouse keeper’s cat has gone missing, and the lamp won’t feel right until she’s home.", "twist": "The cat isn’t lost at all; she has been busy with something far more important than supper.", "open": "The Tideglass lighthouse keeper hasn’t slept. His cat, {cat_name}, has never missed supper, and her bowl of sardines sits untouched by the lamp room door.", "steps": ["By {place} you find cat fur caught on a barnacle, and a line of paw prints heading toward the low-tide caves.", "{critter} reports that a cat has been carrying sardines away one at a time, very seriously.", "Inside the first cave, the paw prints are joined by smaller prints, wobbly and many.", "The keeper’s tide chart says the caves flood gently by {hour}, so you hurry, but not too much.", "Deep in a dry nook, you hear a chorus of thin mews and one patient, rumbling purr.", "{cat_name} blinks at you from a nest of {nest}, {kitten_count} kittens tucked around her paws."], "end": "You carry the basket of {kitten_count} kittens up the lighthouse stairs while {cat_name} supervises every step. The keeper laughs, the lamp turns, and the missing sardines make sense.", "vars": {"cat_name": ["Marmalade", "Biscuit", "Captain Whiskers", "Toffee"], "kitten_count": ["four", "three", "five"], "nest": ["old sailcloth", "a coil of fishing net", "a pile of spare signal flags"]}},
  {"id": "r-sky-whale-calf", "style": "rescue", "title": "A Calf Adrift Among the Isles", "hook": "A sky-whale calf has lost its pod, and its lonely song is rattling every window on the isles.", "twist": "The pod hasn’t gone far; they simply can’t hear the calf over something new.", "open": "A sky-whale calf the size of a barn bumps gently against the Starfall docks, singing a single worried note. Its pod passed through last night and didn’t come back.", "steps": ["At {place} a ferry captain shows you {token} shed from the calf, still ringing faintly with its song.", "The calf follows you like a puppy, but only when you hum its note back to it.", "{helper} says whale pods travel toward {star} and call to each other every sunset.", "On the highest isle, a festival has hung hundreds of new {chimes}, clattering louder than any whale.", "The festival folk agree to hush their {chimes} for a single sunset, tying each one with ribbon.", "In the quiet, you hold up {token}, still ringing, and a deep, answering song rolls in from the clouds."], "end": "Under {weather}, the pod rises toward {star}, and the calf swims up to meet them, singing all the way. The festival unties its {chimes}, and they ring softer now.", "vars": {"token": ["a barnacle", "a silver scale", "a curl of cloud-kelp"], "star": ["the evening star", "the rising moon", "the northern lights"], "chimes": ["wind chimes", "tin bells", "glass chimes", "bamboo rattles"]}},
  {"id": "r-snowed-in-postal-crew", "style": "rescue", "title": "The Mail Cabin Under the Snow", "hook": "A postal crew is snowed into their mountain cabin, and the whole valley is waiting on {letters}.", "twist": "The sled dogs have been trying to reach the crew all along, just from the wrong side.", "open": "A storm buried the Frostbell postal cabin overnight. Smoke still curls from the chimney, so the crew is cozy, but three sacks of {letters} are stuck with them.", "steps": ["Near {place} you find {clothing} on a signpost, with a note tucked inside: “Tell the dogs we’re fine.”", "Down the slope, a team of {dog_count} sled dogs is circling an empty snowbank, barking at nothing.", "{helper} says the cabin’s front door faces the cliff, so everyone really uses the back window.", "You follow the chimney smoke uphill and see the dogs have been digging at the front all morning.", "With a borrowed shovel and {dog_count} eager helpers, you start a tunnel toward the back window.", "A knock comes from inside, then laughter, and a bundle of mail is passed out through the frost."], "end": "You read the note aloud, the dogs wag themselves silly, and the crew hitches the sled. The {letters} reach {village} by {hour}, and one of them is addressed to you.", "vars": {"letters": ["birthday letters", "holiday cards", "valentines", "seed catalogs"], "clothing": ["a mitten", "a wool sock", "an earmuff", "a knitted cap"], "dog_count": ["eight", "six", "ten"]}},
  {"id": "r-tortoise-long-way", "style": "rescue", "title": "The Tortoise Who Took the Long Way", "hook": "Mosswood’s oldest tortoise left for his yearly stroll and hasn’t come back for the acorn feast.", "twist": "He isn’t lost; the path he has walked for eighty years simply isn’t there anymore.", "open": "Old Hollis the tortoise walks the same loop through Mosswood every autumn. This year the feast is ready, his chair is empty, and his favorite {cake} is going cold.", "steps": ["At {place} you find his {hat} hanging on a fern, neatly, as if he meant to come back for it.", "{critter} tells you Hollis stops every afternoon to nap in the warmest patch of sun he can find.", "His slow, careful footprints lead past {landmark} to a wide stream that wasn’t there last year.", "Beavers explain they built a new pond this summer, and the old stepping stones are underwater now.", "Across the water, a sunbeam lands on a flat rock, and on it sits a very patient, very sleepy tortoise.", "You and the beavers roll a log into place, making a low, sturdy bridge just wide enough for a shell."], "end": "Hollis wakes, puts on the {hat} you carried for him, and crosses slowly to applause. At the feast, he names the new bridge after you and eats two slices of {cake}.", "vars": {"cake": ["acorn cake", "hazelnut pie", "blackberry tart", "chestnut loaf"], "hat": ["walking hat", "tweed cap", "straw hat"]}},
  {"id": "r-paper-dragon-treetops", "style": "rescue", "title": "The Paper Dragon in the Treetops", "hook": "A child’s paper kite came alive in the wind and is now tangled high in Mosswood’s canopy.", "twist": "The kite doesn’t want to come down; it’s afraid landing will make it plain paper again.", "open": "{child}’s kite, painted like a dragon, caught a strange breeze and blinked awake. Now it’s snagged on {tree} in Mosswood, its string trailing far below.", "steps": ["Beneath {place} you find the kite’s tail ribbons, each one painted with a tiny word in {child}’s handwriting.", "{child} explains there’s a wish on every ribbon: “fly,” “see far,” “be brave,” and “come home.”", "{critter} shows you a route up {tree}, branch by branch, as long as you keep your voice gentle.", "Halfway up, you see the kite has nibbled through its own string, trying to stay in the sky.", "The kite admits it has never landed, and it isn’t sure what it would be if it did.", "Under {weather}, you read it the last ribbon, “come home,” and say {child}’s house has a window facing the wind."], "end": "The paper dragon glides down into {child}’s arms, still blinking. It hangs by the open window now, where it flies every breezy evening and always comes home.", "vars": {"child": ["Wren", "Tilly", "Juniper", "Moss"], "tree": ["the tallest oak", "the oldest beech", "a towering pine"]}},
  {"id": "r-firefly-troupe", "style": "rescue", "title": "The Fireflies Who Lost the Beat", "hook": "The traveling firefly troupe is lost somewhere in Mosswood, and tonight’s show can’t start without them.", "twist": "The troupe hasn’t lost their way; they’ve lost the one who keeps them together.", "open": "A stage of mushrooms waits in a Mosswood clearing, but the firefly troupe never arrived. The audience of {audience} is getting restless, and the moon is almost up.", "steps": ["At {place} you find a program no bigger than a leaf, listing a conductor named {conductor}.", "{critter} saw a cloud of lights drifting in circles near the brambles, blinking out of rhythm.", "In the brambles, the fireflies swirl in confusion, each one flashing whenever it pleases.", "They tell you {conductor} keeps the beat on a tiny {drum}, and without it they forget the song.", "A faint tap-tap-tap leads you to a spiderweb, where a small firefly waits politely to be untangled.", "The spider helps you free {conductor}, whose only worry is that the show started without her."], "end": "{conductor} raises her {drum}, and the clearing lights up in rhythm. The {audience} stomp for an encore, and the spider takes a front-row seat and shares {snack}.", "vars": {"conductor": ["Flick", "Spark", "Glimmer", "Tinder"], "drum": ["acorn drum", "walnut drum", "thimble drum"], "audience": ["rabbits", "field mice", "toads", "voles"]}},
  {"id": "r-fawn-green-fence", "style": "rescue", "title": "The Fawn on the Wrong Side of the Fence", "hook": "A shy fawn is stuck on the wrong side of a farmer’s new fence, and its mother waits just out of sight.", "twist": "The fence has had a gate all along; it just blends in a little too well.", "open": "At the edge of Mosswood, near {village}, a spotted fawn paces along a brand-new fence, calling for its mother. The farmer who built it wants to help, but the fawn won’t let anyone near.", "steps": ["Near {place} you spot a doe watching from the ferns, ears turned toward every small sound.", "The farmer says he painted the whole fence green so it would disappear into the woods.", "The fawn backs away from people, but its ears perk up at the crunch of {treats}.", "Walking the fence toward {landmark}, you notice one section with hinges hidden under green paint.", "The gate is stiff, so the farmer fetches oil and you work the latch loose together.", "You roll a trail of {treats} through the open gate, and the fawn follows, one careful step at a time."], "end": "The fawn bounds to its mother, and the two vanish into the ferns. The farmer paints the gate {gate_color} and leaves a bucket of {treats} beside it every week.", "vars": {"treats": ["apples", "pears", "carrots", "turnips"], "gate_color": ["bright yellow", "cherry red", "sky blue"]}},
  {"id": "r-octopus-in-teapot", "style": "rescue", "title": "The Octopus in the Teapot", "hook": "A young octopus has squeezed into a teapot at the harbor market and can’t find the way back to sea.", "twist": "The octopus could slip out anytime; it just has no idea which way the sea is.", "open": "At the harbor market in {village}, a porcelain teapot keeps lifting its own lid. Inside, a nervous octopus has made a home, and the tea merchant would like her pot back.", "steps": ["Near {place} you find a trail of wet ink spots leading from the fish stalls to the tea stall.", "The merchant says the teapot came from a shipwreck and still smells faintly of {scent}.", "The octopus peeks out, changing color to match whatever cup you hold up.", "{helper} explains young octopuses follow the smell of the sea, but the market smells of everything else.", "You carry the teapot past {stalls}, and the octopus grows paler and more worried.", "At the end of the pier, a salty breeze rolls in, and one curious arm reaches out toward it."], "end": "The octopus slides into the cool water, then returns the teapot lid with a polite splash. The merchant keeps that pot on her top shelf, and it still smells of {scent}.", "vars": {"scent": ["salt", "seaweed", "brine"], "stalls": ["spice sellers and bakers", "cheese sellers and florists", "candle makers and cooks"]}},
  {"id": "r-figurehead-brave-kettle", "style": "rescue", "title": "The Figurehead and the Brave Kettle", "hook": "A carved wooden figurehead has washed ashore, and she’d very much like to see her old ship again.", "twist": "Her ship never sank; it just stopped sailing and started doing something else.", "open": "On Tideglass Coast, a wooden figurehead with a chipped nose and a painted smile lies on the sand, asking everyone who passes about a ship called the Brave Kettle.", "steps": ["At {place} {helper} checks the old harbor books and finds the Brave Kettle last docked {years} years ago.", "The figurehead remembers the smell of {spice} from the galley, and a cook who sang off-key.", "A retired sailor says the Kettle was hauled up the beach one spring and never went back out.", "You follow the shore past {landmark} toward a hull-shaped building with round windows.", "The smell of {spice} reaches you before the sign does: The Brave Kettle Bakery.", "Inside, a gray-haired baker is singing, very off-key, over a tray of buns."], "end": "The baker gasps, then laughs, and you all fix the figurehead above the bakery door. Now she greets every customer, and each {spice} bun comes with a free wink.", "vars": {"spice": ["cinnamon", "cardamom", "ginger", "nutmeg"], "years": ["ten", "twenty", "thirty"]}},
  {"id": "r-wind-up-wren", "style": "rescue", "title": "The Wind-Up Wren Without a Key", "hook": "A clockwork songbird is winding down in the ruins, and its key is missing.", "twist": "The key wasn’t lost; another small machine has been using it to keep going.", "open": "In the Clockwork Ruins, a brass wren sings a little slower every hour. The keyhole in its back is empty, and it can only sing until {hour} tomorrow.", "steps": ["At {place} you find a trail of tiny brass feathers, each one engraved with a musical note.", "The wren says its maker lived in the tower with the {door} door and wound it every morning.", "Behind the {door} door is a dusty workshop, with a sketch of a key shaped like {key_shape}.", "Faint ticking leads you to a clockwork mouse, snoring, the key shaped like {key_shape} in its side.", "The mouse wakes, apologetic, and explains it borrowed the key after losing its own years ago.", "In the maker’s drawer, beside {trinket}, you find a spare mouse key, small and exactly the right size."], "end": "You wind both machines, the mouse with its new key and the wren with its old one. The wren sings the notes from its feathers in order, and the mouse keeps time with its tail.", "vars": {"door": ["green", "blue", "crimson", "yellow"], "key_shape": ["a treble clef", "a tiny quarter note", "a curly sharp sign"]}},
  {"id": "r-apprentice-gear-maze", "style": "rescue", "title": "The Apprentice in the Gear Maze", "hook": "A tinker’s apprentice went into the gear maze for a spare spring and hasn’t come out.", "twist": "The maze keeps shifting because the apprentice keeps turning cranks, trying to find the way out.", "open": "The gear maze in the Clockwork Ruins shifts every hour. Tinker Osk’s apprentice, {apprentice}, went in at breakfast with a {lunch} and a ball of {yarn} yarn. It’s nearly supper.", "steps": ["At {place} you find the end of {apprentice}’s {yarn} yarn, tied neatly to a gear tooth.", "The yarn goes taut, then slack, as the walls grind a quarter-turn and settle again.", "Osk explains that every crank in the maze moves a different wall, and {apprentice} loves turning cranks.", "{critter} sits by an empty {lunch} on a ledge, beside a note: “Going left. Left is always right, right?”", "You stop touching cranks and follow the yarn, and for once the walls hold still.", "Around a corner, {apprentice} sits on a crate, surrounded by cranks labeled in chalk."], "end": "{apprentice} hands you a chalk map, and you walk out together along the {yarn} yarn. Osk shares {snack}, frames the map, and names {apprentice} Official Maze Labeler.", "vars": {"apprentice": ["Bea", "Pim", "Nell", "Otto"], "yarn": ["red", "yellow", "sky-blue", "green"], "lunch": ["lunch pail", "picnic basket", "tin lunchbox"]}},
  {"id": "r-brass-sheepdog", "style": "rescue", "title": "The Brass Sheepdog’s Scattered Flock", "hook": "A clockwork sheepdog has lost its whole flock of brass sheep, and it can’t stop pacing.", "twist": "The sheep didn’t run off; they’re following a tune they no longer recognize.", "open": "In the Clockwork Ruins, a brass sheepdog named {dog} circles a meadow of copper grass. Its {flock_count} wind-up sheep wandered off in the night, and {dog} can only whistle and wait.", "steps": ["Near {place} you find a brass sheep stuck in a ditch, bleating a tinny little tune.", "{dog} whistles, and the sheep trots the wrong way, as if it heard something else entirely.", "You gather three more sheep behind {landmark}, all humming the same old tune.", "A traveling repair-gnome admits she tuned {dog}’s whistle last week, to make it prettier.", "The gnome digs {dog}’s original whistle reed out of her toolbox, bent but fixable.", "With the old reed in place, {dog} tries a note, and bleats answer from all over the ruins."], "end": "Under {weather}, {flock_count} brass sheep trot home in a neat line, and {dog} counts them twice. The gnome keeps the pretty reed and plays it only on {day}.", "vars": {"dog": ["Rivet", "Sprocket", "Bolt", "Cog"], "flock_count": ["twelve", "nine", "fifteen"], "day": ["Sundays", "birthdays", "rainy days"]}},
  {"id": "r-glowworm-too-deep", "style": "rescue", "title": "The Glowworm Who Went Too Deep", "hook": "A young glowworm wandered into the deep caverns, and its family’s ceiling is missing one small star.", "twist": "The glowworm is trying to come home; it just keeps following the wrong light.", "open": "The glowworms of Lantern Hollows make a ceiling like a night sky, and every family knows its own pattern. Tonight one star is missing, and {elder} is worried.", "steps": ["At {place} {elder} shows you the family pattern, shaped like {mark}, with one gap in it.", "{critter} saw a tiny glow crawling downward, toward the crystal pools.", "Near the pools, the crystals reflect every light, and a dozen tiny glows flicker back at you.", "Only one of the glows is moving, and it keeps inching toward its own reflection.", "A blind cave fish suggests the glowworm will follow a pattern it knows, not a single light.", "You gather lantern beetles and arrange them in the family’s shape, like {mark}, gap and all."], "end": "The little glowworm crawls toward the familiar shape and all the way home. By {hour}, the ceiling of Lantern Hollows is complete again, and {elder} glows twice as bright.", "vars": {"elder": ["Grandmother Gleam", "Grandfather Glint", "Auntie Shimmer"], "mark": ["a small curling tail", "a tiny crescent", "a little five-point star"]}},
  {"id": "r-pony-followed-bread", "style": "rescue", "title": "The Pony Who Followed the Bread", "hook": "The baker’s pony has wandered into the caverns, and nobody knows how she got past the gate.", "twist": "The pony isn’t lost; she’s been visiting someone down there every night.", "open": "Every morning, the baker’s pony pulls the bread cart through Lantern Hollows to {village}. Today the cart stands empty, the gate is locked, and there are hoofprints on the wrong side of it.", "steps": ["Near {place} you find breadcrumbs, not scattered but placed in a neat line, one every few steps.", "The baker admits a {loaf} goes missing each night, and she had assumed it was mice.", "The hoofprints lead past {landmark} to a narrow side passage the gate was never built to close.", "Deep inside, you hear crunching, and a low, happy rumble that definitely isn’t a pony.", "In a warm grotto, the pony stands beside a shy rock troll, sharing a {loaf}.", "The troll explains it can’t go up into daylight, so the pony has been bringing breakfast down."], "end": "The baker bakes an extra {loaf} every morning now, labeled for the troll. The pony delivers it before her rounds, and the troll sends back {gift}.", "vars": {"loaf": ["crusty loaf", "seeded loaf", "braided loaf", "rye loaf"], "gift": ["mushrooms for the pies", "glowing moss for the windows", "smooth stones for the garden path"]}},
  {"id": "r-golem-child-blue-wall", "style": "rescue", "title": "The Small Stone and the Humming Wall", "hook": "A tiny golem child has rolled away from its family, and the caverns are too big to search alone.", "twist": "The golem’s family has been calling all along, in a hum too low for ears.", "open": "In Lantern Hollows, a golem no bigger than {size} rocks back and forth, clicking softly. It rolled down a slope while its family napped, and it can’t climb back up.", "steps": ["At {place} the little golem shows you a streak of {crystal} crystal on its side, like a birthmark.", "{helper} says golem families sleep inside a wall of that same {crystal} crystal, deep in the hollows.", "The golem clicks faster near certain walls, then stops, confused.", "Pressing your palm to the stone, you feel a low hum, steady as a heartbeat.", "You follow the hum past {landmark}, the little golem riding in your pocket and clicking along.", "The passage opens onto a glowing {crystal} wall, humming so deep your boots tingle."], "end": "The wall shifts, and a huge stone hand reaches out, gently, for the little golem. The family hums a thank-you so low it rattles your buttons, and you hum back your best.", "vars": {"crystal": ["blue", "violet", "pale green", "amber"], "size": ["a teacup", "a thimble", "a pinecone"]}},
  {"id": "r-ducklings-in-fog", "style": "rescue", "title": "Seven Ducklings and a Fog Bank", "hook": "A mother duck has lost her ducklings in the Whisperfen fog, and she can only count to three.", "twist": "The ducklings aren’t scattered at all; they’re following a leader who isn’t their mother.", "open": "Fog rolled over Whisperfen at breakfast, and Mother Dabble lost sight of her ducklings. She can count to three before she gets flustered, so she isn’t sure how many are missing.", "steps": ["Near {place} you find a single downy feather caught on a reed, still warm.", "{critter} reports a line of peeping heading {direction}, very orderly.", "Mother Dabble explains her smallest duckling, {little_one}, always wants to go first.", "You follow the peeping {direction} into the fog and hear a tiny voice calling, “This way, everyone!”", "A heron offers to stand tall on {landmark} so the ducklings have something to steer toward.", "The fog thins, and there is {little_one}, marching proudly, with six siblings in a perfect line behind."], "end": "You help Mother Dabble count, one through seven, twice. {little_one} leads the way home, and nobody minds, because this time Mother Dabble paddles right alongside.", "vars": {"little_one": ["Pond", "Puddle", "Dot", "Ripple"], "direction": ["east", "west", "north"]}},
  {"id": "r-ferryman-reed-island", "style": "rescue", "title": "The Ferryman on the Floating Reeds", "hook": "The ferryman of {village} is stranded on a drifting island of reeds, and his raft floated off without him.", "twist": "The island is drifting because it isn’t exactly an island.", "open": "Old {ferryman} stepped onto a reed island to pick {herb}, and his raft slipped its rope. Now he waves from the island, which seems to be moving slowly downstream.", "steps": ["At {place} you find his raft snagged on a stump, its rope chewed clean through.", "A muskrat confesses to the chewing; it wanted the rope for its nest and is very sorry.", "The reed island is drifting against the current, which islands really shouldn’t do.", "Wading closer, you spot two large, old eyes blinking sleepily just under the reeds.", "The muskrat offers a length of braided grass as a new rope, strong and freshly woven.", "You pole the raft alongside, toss {ferryman} the grass rope, and he steps across with his {herb}."], "end": "The turtle yawns and paddles off with its reeds. Under {weather}, {ferryman} brews {herb} tea for you and the muskrat, who gets to keep the old rope.", "vars": {"ferryman": ["Tamsin", "Barnaby", "Fennick"], "herb": ["marsh mint", "sweet flag", "water mint", "wild sorrel"]}},
  {"id": "r-lost-will-o-wisp", "style": "rescue", "title": "The Will-o’-Wisp Who Got Lost", "hook": "A will-o’-wisp who usually leads travelers astray has gotten itself thoroughly lost.", "twist": "The new posts were put up to help travelers, and they do; nobody thought to ask the wisp.", "open": "In Whisperfen, a small {color} wisp bobs miserably above a puddle. For {years} it has led travelers in playful circles, and now it can’t find its own way home.", "steps": ["Near {place} the wisp explains it has always found home by three crooked posts.", "A marsh warden says the crooked posts were replaced last month with neat, straight ones.", "The wisp flickers with embarrassment; to it, straight posts all look exactly the same.", "In the warden’s shed, you find the three old crooked posts, stacked for firewood.", "You and the warden carry them out and plant them near {landmark}, where the wisp remembers.", "The wisp zips from post to post, glowing brighter {color} each time, humming a tune it had nearly lost."], "end": "The wisp finds its hollow and glows proudly until {hour}. Now, when travelers get lost, it leads them home along the crooked posts, just to say thank you.", "vars": {"color": ["blue", "green", "silver", "violet"], "years": ["a hundred years", "three hundred years", "longer than anyone remembers"]}},
  {"id": "r-yak-calf-bell", "style": "rescue", "title": "The Yak Calf and the Silent Bell", "hook": "A yak calf strayed from the herd in a snow squall, and its tiny bell has gone quiet.", "twist": "The bell isn’t broken, and the calf isn’t in any hurry.", "open": "The herders of Frostbell Pass count their yaks by bell. Tonight there are {bell_count} bells ringing, and one small, silent calf named {calf} is missing.", "steps": ["At {place} you find a tuft of shaggy brown fur caught on a thornbush, frost on every tip.", "{helper} says {calf} loves licking salt from the rocks by the old shrine.", "Near the shrine, small hoofprints circle a salt rock, then wander uphill.", "{critter} tells you something shaggy is napping in a drift below the ridge.", "You find {calf} curled up in the drift, warm and content, bell packed full of snow.", "You knock the snow loose, and the bell rings, clear and bright across the pass."], "end": "Under {weather}, {calf} trots home ringing, and the herd answers with {bell_count} bells. The herders hang a salt lick by the shrine and give you a bell of your own.", "vars": {"calf": ["Tuft", "Nib", "Burr", "Mossy"], "bell_count": ["forty-one", "twenty-six", "thirty-three"]}},
  {"id": "r-snowman-walked-downhill", "style": "rescue", "title": "The Snowman Who Walked Downhill", "hook": "A snowman came alive and wandered downhill toward the warm valley, and he’s getting smaller.", "twist": "He isn’t running away; he’s looking for the two people who built him.", "open": "Somewhere below Frostbell Pass, a snowman with {nose} and a {scarf} scarf is melting, one step at a time. He left his hill last night and hasn’t looked back.", "steps": ["At {place} you find a trail of round footprints, each one smaller and slushier than the last.", "{helper} saw the snowman stop at every farmhouse and peer into the windows.", "The {scarf} scarf, you learn, was knitted by {kids} who moved down to {village} this winter.", "You find the snowman in a shady barn, much shorter now, asking the goats for directions.", "He explains the {kids} built him, then left before he could say goodbye.", "A sledge driver offers to haul the snowman, packed in fresh snow, straight to their door."], "end": "The {kids} run out shrieking with joy and pack their snowman taller than ever in the porch’s shade. Every winter after, they build him on that spot, and he always waves.", "vars": {"nose": ["a carrot nose", "a pinecone nose", "a parsnip nose"], "scarf": ["red", "striped", "green", "plaid"], "kids": ["twins", "two sisters", "two brothers"]}},
  {"id": "r-camel-chased-mirage", "style": "rescue", "title": "The Camel Who Chased a Mirage", "hook": "A caravan’s lead camel wandered off after a shimmering mirage, and the caravan won’t move without her.", "twist": "The mirage may not have been a mirage at all.", "open": "A caravan in the Amber Expanse has stopped cold. Their lead camel, {camel}, saw something shimmer at noon and trotted toward it, and none of the others will walk without her.", "steps": ["At {place} you find {camel}’s tasseled halter dropped near {landmark}, its tassels pointing {direction}.", "A caravan elder says {camel} has always found water, but she’s never chased a mirage before.", "{critter} tells you the shimmer only appears when the sun is directly overhead.", "You wait for noon, and the {direction}ern horizon wavers into {trees} and blue water.", "You walk toward it, and this time it doesn’t fade; there is cool grass underfoot.", "By a spring, {camel} is drinking happily, surrounded by {trees} nobody has ever mapped."], "end": "You slip on her halter, and {camel} leads the whole caravan to the oasis to rest and drink. The elder marks it on the map with a tiny camel, in her honor.", "vars": {"camel": ["Saffron", "Clementine", "Duna"], "trees": ["date palms", "fig trees", "pomegranate trees"], "direction": ["west", "east", "south"]}},
  {"id": "r-fiddler-in-dunes", "style": "rescue", "title": "The Fiddler Lost in the Dunes", "hook": "A traveling fiddler got separated from her troupe in a sandstorm, and the festival starts at moonrise.", "twist": "{fiddler} isn’t lost at all, at least not in her own opinion.", "open": "The Amber Expanse festival stage is ready, but the troupe’s fiddler, {fiddler}, vanished in yesterday’s sandstorm. Her bandmates are rehearsing without her, badly.", "steps": ["At {place} you find a fiddle string wrapped around a cactus, tied in a neat bow.", "The drummer says {fiddler} ties a bow on anything she wants the band to notice.", "More bows appear, on {markers}, all pointing toward a canyon.", "In the canyon you hear fiddle music, but it seems to come from every direction at once.", "{critter} tells you the canyon bends sound around corners, so follow the bows, not the music.", "The last bow is tied to a tent pole, where {fiddler} is fiddling happily for a family of {audience}."], "end": "The {audience} share {snack} and insist on coming along. At moonrise, {fiddler} plays her best tune yet, with a row of large ears perked up at the front.", "vars": {"fiddler": ["Juno", "Marigold", "Tess", "Ottilie"], "markers": ["a rock, a bone, and a signpost", "a boot, a cactus, and a fence post", "a jar, a skull, and a wagon wheel"], "audience": ["fennec foxes", "desert hares", "sand cats"]}},
  {"id": "r-stargazer-glass-ridge", "style": "rescue", "title": "The Stargazer on Sandglass Ridge", "hook": "A glassblower’s grandfather went out to count shooting stars, and his sand-sled came home without him.", "twist": "{grandpa} isn’t lost; he simply can’t find a way down.", "open": "In the Amber Expanse, lightning once turned a dune ridge into smooth, slippery glass. Grandpa {grandpa} climbed up to watch shooting stars, and his sled slid home to {village} alone.", "steps": ["At {place} the glassblower shows you the sled, missing its left runner.", "She explains {grandpa} always carries {signal} to flash a message home when he’s done.", "From the foot of the ridge, you see a flash of light, blinking slow and patient.", "The ridge is too slick to climb, and your boots slide right back down.", "{helper} lends you a coil of strong rope and a heavy grappling hook.", "You find the left runner half buried in sand and drive it in as an anchor for the rope."], "end": "{grandpa} slides down the rope, grinning, with a notebook full of shooting stars. The glassblower builds him a new sled with glass runners, perfect for the ridge.", "vars": {"grandpa": ["Orrin", "Tobias", "Wendell"], "signal": ["a hand mirror", "a polished spoon", "a brass compass lid"]}},
  {"id": "r-balloonist-smallest-isle", "style": "rescue", "title": "The Balloonist on the Smallest Isle", "hook": "A balloonist is stuck on a floating rock no bigger than a kitchen table, and her balloon drifted off.", "twist": "The balloon isn’t lost; it has been adopted.", "open": "Somewhere among the Starfall Isles, a balloonist named {pilot} waves from a rock the size of a table. Her balloon, striped {stripes}, drifted away while she was sketching.", "steps": ["At {place} {helper} lends you a spyglass, and you spot {pilot}’s rock and her waving scarf.", "{pilot} shouts across the gap that the basket holds {horn} she uses to signal.", "{critter} saw a flock of cloud geese pass at noon, honking at something {stripes}.", "You find the balloon nestled in the middle of the flock, the geese honking at it fondly.", "Reaching the basket, you lift out {horn} and give it one careful blast.", "The geese honk back, then nudge the balloon toward you, like returning a friend."], "end": "You steer the balloon to {pilot}’s rock, and she climbs aboard with her sketchbook. On the way home, the cloud geese fly escort, and {pilot} draws every one of them.", "vars": {"pilot": ["Pell", "Quill", "Marigold"], "stripes": ["red and gold", "blue and white", "green and orange"], "horn": ["a brass horn", "a tin trumpet", "a copper bugle"]}},
  {"id": "m-mushroom-alphabet", "style": "mystery", "title": "The Mushrooms That Learned to Spell", "hook": "Every morning the mushrooms of Mosswood are standing in new letters, and nobody planted them that way.", "twist": "The letters aren’t a warning. They’re a draft, and someone keeps fixing the spelling.", "open": "Overnight, the mushroom rings of Mosswood have rearranged themselves into wobbly letters. Today they spell “THNAK,” and the forest is baffled.", "steps": ["Near {place} a mushroom lies tipped on its side, and beside it sits a little pile of {pieces} with scratches inside.", "{helper} says the mushrooms shift just before dawn, to the sound of someone counting under their breath.", "A trail of small paw prints stops at every ring, each set pausing as if its owner read the word over and frowned.", "The newest ring now reads “THANK YUO,” so whoever it is, they are getting closer to right.", "Under a fern you find a whole stack of {pieces}, each with a letter scratched inside: a homemade alphabet.", "A young hedgehog admits the letters are for {rescuer}, who carried her out of a flooded burrow {when}."], "end": "You help the hedgehog swap the last two mushrooms. The ring reads “THANK YOU,” and {rescuer} stands before it a long, happy while, then shares {snack}.", "vars": {"pieces": ["acorn caps", "hazelnut shells", "beech husks", "empty snail shells"], "rescuer": ["the old badger", "a gruff old otter", "the retired mole postman", "the kindly heron"], "when": ["last spring", "in the autumn floods", "during the big thaw"]}},
  {"id": "m-ceiling-footprints", "style": "mystery", "title": "Footprints on the Ranger’s Ceiling", "hook": "Muddy footprints cross the ceiling of the ranger’s hut every night, and her spare boots keep turning up warm.", "twist": "The boots aren’t being worn on anyone’s feet. They’re being carried, upside down.", "open": "The ranger of {village} points up. A neat line of tiny muddy prints walks across her ceiling, around the lamp, and out through the chimney.", "steps": ["Near {place} you find a flake of dried mud with a fleck of {moss} in it, the kind that only grows upside down.", "Over {snack}, the ranger mentions her {boots}, the pair her niece outgrew, keep going missing and coming back warm.", "A trail of {moss} flakes leads from the chimney to a hollow oak where the air smells like wet stone.", "Inside the hollow, the ceiling is covered in tiny footprints, crisscrossing as if someone has been pacing.", "The niece’s {boots} hang from a knot, swaying gently with something small curled inside each one.", "Two young bats peek out; they have been walking the boots home across ceilings, because the nights are cold and boots are cozy."], "end": "The ranger makes two {socks} and hangs them in the rafters of the oak. The bats move in that night, and her ceiling stays spotless.", "vars": {"moss": ["cave moss", "silver lichen", "glow moss", "velvet moss"], "boots": ["smallest boots", "little red wellies", "felt booties", "fur-lined boots"], "socks": ["woolly sleeping socks", "knitted mitten-beds", "felted sleeping pouches"]}},
  {"id": "m-thinner-book", "style": "mystery", "title": "The Book That Came Back Thinner", "hook": "A library book keeps returning itself to the Mosswood lending tree, one chapter shorter each time.", "twist": "The missing pages aren’t lost. They’re being mailed, one chapter at a time.", "open": "The lending tree’s copy of “{book}” is back on its shelf again, overdue by nobody, and now missing {chapter}.", "steps": ["Near {place} you find a torn page edge caught on a bramble, the paper still smelling faintly of pond water.", "The librarian owl shows you the checkout slip: every line is signed with a small, careful drawing of {sign}.", "{helper} says paper boats float past each evening, each one folded from a single printed page.", "You follow the boats to a quiet pond below {landmark}, where the reeds lean in as if listening to a story.", "On a sunny rock sits a stack of dried, flattened pages in perfect chapter order, pinned under a smooth pebble.", "An old tortoise explains the walk takes her three days, so her grandson, who signs with {sign}, sends the story by boat."], "end": "The librarian owl declares the pond an official branch of the lending tree. The tortoise gets her own copy and shares {snack}, and the boats keep coming anyway.", "vars": {"book": ["The Heron’s Long Winter", "The Otter Who Sailed", "A Year of Small Suppers", "Moonrise Over the Millpond"], "chapter": ["chapter nine", "chapter four", "the twelfth chapter"], "sign": ["a shell", "a four-leaf clover", "a tiny pond lily", "a curled fern"]}},
  {"id": "m-tide-gone-out", "style": "mystery", "title": "The Tide That Went Out for Good", "hook": "The tide at Tideglass Coast went out {day} and has not bothered to come back.", "twist": "The tide isn’t gone. It’s waiting for something it lost.", "open": "The boats of Tideglass Coast sit on wet sand, tilted like sleepy cats. The sea is a silver line on the horizon, and it isn’t moving.", "steps": ["Near {place} you find the lid of a {jar} in the sand, a fleck of silver light still stuck to its rim.", "{helper} says the tide always follows the moon’s reflection home, and last night the water was dark all the way out.", "Tangled in the drying nets you find a single strand shining silver, knotted in a child’s clumsy bow.", "By the dunes you spot {critter} watching a girl in a {coat} carry a {jar} and talk to it softly.", "In a hollow of the dunes sits a hidden shelf of treasures: a shell, a feather, and a scrap of moonlight in a {jar}.", "The girl explains she scooped the reflection from a rock pool because it looked lonely, and only meant to keep it one night."], "end": "You walk her to the waterline and she tips the {jar} out. The moonlight skates across the sand, the sea follows it home, and the boats float up to say goodnight.", "vars": {"day": ["on Tuesday", "three days ago", "last Thursday", "at the weekend"], "jar": ["jam jar", "pickle jar", "honey pot", "sweet jar"], "coat": ["yellow raincoat", "striped jumper", "red wool hat", "fisher’s smock"]}},
  {"id": "m-shell-doorbells", "style": "mystery", "title": "The Seashells That Ring at Midnight", "hook": "Every shell on the beach has started ringing like a doorbell after dark, and nobody is ever there.", "twist": "The ringing isn’t someone at the door. It’s someone looking for one.", "open": "At midnight the beach at {village} goes ding, ding, ding. The villagers open their doors, find no one, and go back to bed grumbling.", "steps": ["Near {place} you find {clapper} tied to a strand of seaweed, swinging like a doorbell pull.", "{helper} says the ringing always starts at the high-water line and moves along the beach, one shell at a time.", "Shells lie in neat rows, each with a small arrow drawn in the sand beside it pointing to the next.", "By a tide pool sits a tidy pile of old shells, each one tried on, found too snug, and left behind.", "Scratched on a driftwood post, in very small letters: “Looking for a bigger home. Will knock first.”", "A hermit crab admits it has been house-hunting, ringing every shell with {clapper} so it never walks in on anyone."], "end": "You find {new_home} and ring it once for luck. The hermit crab moves in, the neighbors gather over {snack} for the housewarming, and the beach goes quiet.", "vars": {"clapper": ["a tiny pebble", "a sea-glass bead", "a dried pea", "a limpet shell"], "new_home": ["a roomy spiral shell", "a whelk shell with a view", "a pearly moon shell"]}},
  {"id": "m-blank-bottles", "style": "mystery", "title": "The Bottles with Empty Letters", "hook": "Messages in bottles keep washing ashore at Tideglass, and every single letter inside is blank.", "twist": "The letters were never blank. They were waiting for warmth.", "open": "{count} corked bottles have landed on Tideglass Coast this week. Each holds a folded letter, carefully sealed, with nothing written on it at all.", "steps": ["Near {place} you find a bottle with a {fruit} seed rattling in the bottom, and the paper inside smells faintly sour.", "{helper} says the bottles always drift in from the north, where the old lighthouse stands on its rock.", "The paper curls slightly at one edge, the way paper does when someone has written on it with something wet.", "The lighthouse keeper’s rowboat is tied below the rock, full of empty bottles and a bowl of squeezed {fruit} halves.", "Up the stairs you find a desk with a lamp, a dry pen, and a half-finished letter that looks like nothing at all.", "The shy keeper admits she writes in {fruit} juice so only someone curious enough to try will ever read her letters."], "end": "You hold a letter near the lamp and brown words bloom: {invitation}. By {hour}, half of {village} is climbing the lighthouse stairs, warmed letters in hand.", "vars": {"count": ["Seven", "Five", "Eleven", "Nine"], "fruit": ["lemon", "lime", "grapefruit"], "invitation": ["an invitation to tea", "an invitation to a picnic", "a request for a sing-along"]}},
  {"id": "m-backward-lane", "style": "mystery", "title": "The Street Where Clocks Run Backward", "hook": "On one street in the Clockwork Ruins, every clock has started ticking backward, and only that street.", "twist": "Nobody is breaking the clocks. Someone is trying to get back to a single noon.", "open": "On {lane}, the clocks tick counterclockwise. The neighbors swear their tea goes cold before it’s poured, and everyone is late for yesterday.", "steps": ["At {place} you find a winding key with its teeth filed the wrong way round, still warm from a very small paw.", "{helper} says every clock on the lane reaches noon, pauses, then starts rewinding toward it again.", "A faded poster by {landmark} announces a street concert last month, noon sharp, by {band}.", "A trail of oil drops leads to a narrow attic where a music stand holds a sheet of music with its last line smudged away.", "Inside, a clockwork mouse with a filed key sits beside {instrument}, humming the same few notes and always stopping short.", "The mouse confesses it heard the band once and forgot the ending, so it has been turning the lane back to hear noon again."], "end": "{helper} finds the band’s old music box and lets the mouse listen as often as it likes. The clocks of {lane} ease forward, humming the ending.", "vars": {"lane": ["Cogwheel Lane", "Sprocket Row", "Pinion Street", "Ratchet Alley"], "band": ["a brass band of automatons", "a clockwork marching band", "a trio of tin trumpeters"], "instrument": ["a dented horn", "a tiny tuba", "a brass cornet"]}},
  {"id": "m-wandering-gear", "style": "mystery", "title": "The Gear That Won’t Stay Put", "hook": "One brass gear turns up in a different machine every morning in the Clockwork Ruins, and each machine runs happier for it.", "twist": "The gear isn’t lost. Someone keeps lending it out on purpose.", "open": "A brass gear stamped with {stamp} keeps turning up around the Clockwork Ruins: in the water pump Monday, the lift Tuesday, {machine} today.", "steps": ["At {place} you find a faint scratch on {machine}, as if a small beak pried it open and closed it again very gently.", "{helper} says the water pump sang for a whole day after the gear arrived, then went back to its usual cough.", "A shiny trail of {loot} runs along a crumbling wall, dropped as if someone carried too much at once.", "On a high ledge above {landmark} sits a nest woven from springs, lined with a map where every machine is circled.", "Beside each circle is a note in careful scratches: “sad,” “tired,” “sad,” “very old,” “needs a turn.”", "A clockwork magpie admits it has been visiting the loneliest machines and giving each one its favorite gear for a day."], "end": "The keepers cast a gear stamped with {stamp} for every machine on the magpie’s map. The magpie delivers them itself, one each morning, and the Ruins hum brighter.", "vars": {"stamp": ["a star", "a crescent moon", "a tiny heart", "an oak leaf"], "machine": ["the old organ", "the tea urn", "the weather vane", "the great loom"], "loot": ["bottle caps and buttons", "keys and thimbles", "washers and beads"]}},
  {"id": "m-bow-at-three", "style": "mystery", "title": "Why the Automatons Bow at 3:17", "hook": "Every day at 3:17, every automaton in the Clockwork Ruins stops what it’s doing and bows toward the old tower.", "twist": "They aren’t bowing to the tower. They’re bowing to whoever used to stand in its window.", "open": "At 3:17 exactly, the sweepers, lamplighters, and tea trolleys of the Clockwork Ruins freeze and bow toward the silent tower. Then they carry on.", "steps": ["Near {place} you find a tea trolley’s logbook with the same line on every page: “3:17, remember.”", "{helper} says the tower window once had a {curtain}, but it has been drawn shut for years.", "Behind a loose brick you find a brass plate stamped with a date and a time: the very first day, 3:17, when the automatons woke.", "The tower stairs are swept clean, though nobody admits to sweeping them, and a vase at the top holds a fresh {flower}.", "In the tower room, a workbench sits under a dust cloth, and on it is a card: “Happy waking day, my dears.”", "The eldest sweeper says the builder waved from here every year before retiring {retire}, and they never stopped bowing back."], "end": "You pull open the {curtain} and wave. Every automaton bows, straightens, and waves back, and the Ruins celebrate their first waking day in years over {snack}.", "vars": {"curtain": ["bright red curtain", "blue velvet curtain", "patchwork curtain", "golden curtain"], "flower": ["bolt-flower", "brass tulip", "copper daisy"], "retire": ["to the seaside", "to a cottage by the sea", "to the Starfall Isles"]}},
  {"id": "m-lantern-order", "style": "mystery", "title": "The Lanterns That Light Out of Order", "hook": "The lanterns of Lantern Hollows are lighting themselves in a strange new order each night, and nobody is holding the match.", "twist": "The order isn’t random. It’s drawing a path.", "open": "In Lantern Hollows, the lanterns have always lit from the entrance inward. Tonight they flicker on at random, skipping tunnels and doubling back.", "steps": ["At {place} you find a lantern with a glowworm curled in its wick holder, looking very pleased with itself.", "{helper} shows you the warden’s {chart}; the dots hop about like someone tracing a picture they can’t see.", "The lit lanterns always avoid {hazard} and never pass the loose rocks near {landmark}.", "You join the dots in the {chart} and they make one winding line, from the deepest cavern all the way to the surface.", "At the line’s far end, in the deepest cavern, a colony of glowworms huddles on a ledge above slowly rising water.", "Their eldest explains the cavern floods each autumn, so they’ve been lighting the safest way out, hoping someone would carry them up."], "end": "You and {helper} carry the colony up the lit path in {carriers}. They settle in the lantern by the entrance, where they light the way in for everyone else.", "vars": {"chart": ["lighting chart", "lamp ledger", "wick log"], "hazard": ["the flooded tunnel", "the dripping tunnel", "the drowned stair"], "carriers": ["jam jars", "teacups", "spare lantern globes"]}},
  {"id": "m-shy-stalactites", "style": "mystery", "title": "The Cavern That Hums When You Look Away", "hook": "The stalactites of Lantern Hollows hum a tune, but only when nobody is looking at them.", "twist": "The song isn’t coming from the stone. It’s coming from inside it.", "open": "Deep in Lantern Hollows, a gentle tune drifts down from the stalactites. The moment anyone turns to look, it stops mid-note.", "steps": ["Beneath a hollow stalactite at {place} you find a pinch of chalk dust and a scrap of paper covered in very small musical notes.", "{helper} says the tune changes every week, getting a little longer and a little braver.", "You turn your back on purpose and listen: {count} voices, all trying hard not to be the loudest.", "A {mirror} lets you peek without turning, and you glimpse tiny shapes lined up inside the stone like a choir in pews.", "The tiny sheet music has a title across the top: “For the {recital}, if we are brave enough.”", "A cave cricket steps out, trembling, and admits the choir has practiced for a year but freezes whenever anyone watches."], "end": "You arrange the {recital} with the whole audience facing the wall, eyes shut. The crickets sing all the way through, and {helper} shares {snack} after.", "vars": {"recital": ["Autumn Recital", "Midwinter Concert", "Spring Sing", "Harvest Sing-Song"], "mirror": ["polished quartz mirror", "still, dark pool", "shiny tin lid"], "count": ["a dozen", "twenty", "thirty"]}},
  {"id": "m-late-shadows", "style": "mystery", "title": "The Shadows That Arrive a Minute Late", "hook": "In Lantern Hollows, everyone’s shadow has started showing up about a minute after they do.", "twist": "The shadows aren’t slow. They’re stopping somewhere along the way.", "open": "You step into Lantern Hollows and your shadow doesn’t. It strolls in a full minute later, looking a little dreamy.", "steps": ["Near {place} you notice your shadow pause beside a side tunnel, as if reading a sign you can’t see.", "{helper} says the delays began when that side tunnel was reopened after a rockfall was cleared last month.", "Inside the tunnel, every passing shadow drifts to the same patch of wall and stays there for exactly one minute.", "On a ledge sits an old lantern, still lit, with paper cutouts turning slowly inside it on a tiny {spindle}.", "Its cutouts cast a shadow play on the wall, {story}, in a story that loops every sixty seconds.", "The old puppeteer who made it admits she forgot to switch it off when the tunnel closed, and the shadows got hooked."], "end": "The puppeteer gives {story} a second act and moves the lantern to {landmark}. Now the shadows arrive on time, and everyone stays for the show together.", "vars": {"spindle": ["clockwork spindle", "music-box spindle", "candle-driven spinner"], "story": ["a fox chasing the moon", "a whale learning to fly", "an owl sailing a teacup", "a mouse building a boat"]}},
  {"id": "m-leaning-reeds", "style": "mystery", "title": "The Reeds That All Lean One Way", "hook": "Every reed in Whisperfen has started leaning toward the same spot, even when the wind blows the other way.", "twist": "The reeds aren’t pointing at anything. They’re leaning toward warmth, the way sunflowers turn.", "open": "The reeds of Whisperfen bend in one direction today, all of them, like a crowd craning to see something. The wind blows the other way and they don’t care.", "steps": ["At {place} the water feels oddly warm around your ankles, and the reeds lean harder the farther you wade.", "{helper} mentions the postmistress lost her {stone} off the ferry last week, the round one that glows when heated.", "A frog says the {newts} from his pool all moved out this week, heading toward the middle of the fen.", "You follow the lean of the reeds to a hummock where steam curls up under {weather}.", "Nestled in the mud sits the postmistress’s {stone}, carved with her initials and still toasty as a teapot.", "A family of {newts} is curled on top of it; the fen has turned chilly, and this is the first warm night they’ve had."], "end": "The postmistress decides the {newts} need it more and heats another for herself. The reeds stand up straight, and the little family visits the frog on Sundays.", "vars": {"stone": ["bed-warming stone", "hand-warming pebble", "toasty foot-stone"], "newts": ["newts", "baby toads", "water voles"]}},
  {"id": "m-floating-umbrellas", "style": "mystery", "title": "The Umbrellas That Sailed Away", "hook": "Umbrellas are vanishing from porches all over Whisperfen and turning up floating upside down in the marsh.", "twist": "The umbrellas aren’t being thrown away. They’re being sailed.", "open": "{village} is famous for rain and for umbrellas. This week {count} have gone missing from porches and been spotted drifting through the reeds, handles up.", "steps": ["Near {place} you find an umbrella caught in the reeds, a {flag} tucked in its spokes and a {seat} laid neatly inside.", "{helper} says only the small, bright umbrellas go missing, never the big black ones by the doors.", "A boatman has seen them bobbing in a line, each following the one ahead, like a very slow parade.", "On a muddy bank you find tiny webbed prints and a map of the marsh scratched in the mud, with one pond circled.", "The circled pond is ringed with umbrellas pulled up on the bank, each with a {seat} for a seat and a {flag} for a flag.", "A mother duck admits her ducklings were too small to swim across the fen to the summer pond, so she borrowed boats."], "end": "{helper} sews a fleet of duckling-sized boats, bright and waterproof. The porches get their umbrellas back, each with a thank-you {flag} tied to the handle.", "vars": {"count": ["a dozen", "nine", "fifteen"], "flag": ["feather", "ribbon", "daisy", "dandelion clock"], "seat": ["dry leaf", "lily pad", "moss cushion"]}},
  {"id": "m-fog-letters", "style": "mystery", "title": "The Fog That Writes in Cursive", "hook": "Every day the fog over Whisperfen curls into handwriting, and it always fades before the last word.", "twist": "The fog isn’t a message from the marsh. It’s steam from a very long letter.", "open": "Each day the Whisperfen fog rises in loops and curls: real letters, in a lovely slanted hand. “Dear {sister},” it begins, and then it fades.", "steps": ["Near {place} you smell {scent} in the fog, and the loops grow thicker whenever the wind comes from the east.", "{helper} says the writing appears by {hour} and stops exactly when a kettle would finish boiling.", "East across the fen stands a crooked cottage with a very tall chimney and a kettle of {scent} tea whistling in the window.", "On the sill sits a stack of kettle-shaped stencils, each cut with a line of letters and worn soft from use.", "The cottage belongs to an elderly marsh-witch who has written to her sister {sister} every day for years, one kettle at a time.", "She admits {sister} moved to {village} last spring, on the far side of the marsh, and the steam fades before it gets that far."], "end": "You carry the last stencil to {sister}, who writes back with a much bigger kettle. Now the fog over Whisperfen spells out whole conversations, and both sisters are delighted.", "vars": {"sister": ["Posy", "Maud", "Clementine", "Birdie"], "scent": ["peppermint", "chamomile", "cinnamon", "lemon balm"]}},
  {"id": "m-creeping-snowmen", "style": "mystery", "title": "The Snowmen Who Keep Moving Closer", "hook": "The snowmen of Frostbell Pass creep a little closer to the inn every night, and nobody has seen them move.", "twist": "The snowmen aren’t walking. They’re being rolled, very carefully, by someone small.", "open": "{count} snowmen stood in the meadow at Frostbell Pass on Monday. Today they are right outside the inn, {noses} nearly touching the glass.", "steps": ["Near {place} you find a long groove in the snow behind each snowman, like a sled track with no sled.", "{helper} says the card game by the inn window runs late every night, with lots of laughing and very little winning.", "Tiny pawprints circle each snowman’s base, and a trail of dropped {deck} leads back toward the woods.", "Every snowman now faces the window exactly, stone eyes aimed right at the card table.", "In a snowbank you find a hare’s hideout with a deck of {deck} laid out like cards, each marked in berry juice.", "A young snow hare admits it has been rolling the snowmen closer so it can hide behind them and learn the rules."], "end": "The card players set a small stool by the window and deal the hare in over {snack}. It wins the very first hand, and the snowmen look very proud.", "vars": {"count": ["Five", "Four", "Six", "Three"], "noses": ["carrot noses", "pinecone noses", "parsnip noses"], "deck": ["pine-cone scales", "birch-bark squares", "flat pebbles"]}},
  {"id": "m-windless-bells", "style": "mystery", "title": "The Bells That Ring Without Wind", "hook": "The bells along Frostbell Pass have started ringing on the stillest nights, one after another, up the mountain.", "twist": "The bells aren’t a warning. Someone is using them to find their way.", "open": "Frostbell Pass is lined with bells that ring in the wind. Tonight there is no wind at all, and still they ring, one by one, climbing toward the peak.", "steps": ["At {place} you find a bell with a tuft of {tuft} caught in its clapper.", "{helper} says one of the shepherd’s young goats wandered off in the storm {days} and hasn’t come home.", "The ringing always climbs uphill, bell to bell, then stops at the crooked post by {landmark}, where the path splits.", "At the split, one path lies buried under fresh snow, and the old trail marker is lying face down beside it.", "You set the marker upright; its arrow points toward the shepherd’s valley, down the path the snow had hidden.", "A small goat with a coat of {tuft} steps out of a drift; it has been nudging each bell to count its way home."], "end": "You walk the goat down the uncovered path, ringing each bell once as you pass. The shepherd hears you a mile off and shares {snack} by the fire.", "vars": {"tuft": ["soft white wool", "curly grey fleece", "shaggy brown hair"], "days": ["three days ago", "on Sunday", "two nights back"]}},
  {"id": "m-swapped-mail", "style": "mystery", "title": "The Letters That Went to the Wrong Door", "hook": "Every letter in {village} is arriving at the wrong house, always swapped with the house across the lane.", "twist": "Nobody mixed up the letters. Somebody mixed up the houses.", "open": "In {village} the baker got the blacksmith’s mail and the blacksmith got the baker’s. The same thing happened on every doorstep, in perfect pairs.", "steps": ["Near {place} you notice a house number hanging slightly crooked, its nail freshly bent and still shiny.", "{helper} at the post office insists every letter was sorted correctly, and shows you the numbered cubbies to prove it.", "Up and down the lane, each number sign has traded places with the one across the street.", "A trail of small boot prints zigzags door to door, with the line of a little shovel dragged between them.", "In a shed you find a bucket of scraped ice and a {tool}, and a sign scrubbed so shiny you can see your face.", "The village’s youngest snow-shoveler admits she took every sign down to clear the ice, then hung them back on the wrong side."], "end": "You help her put each sign back and build {cover} over every one. The letters find their doors again, and the whole lane shares {snack} with her.", "vars": {"tool": ["stiff brush", "ice scraper", "wire brush"], "cover": ["a tiny roof", "a little wooden hood", "a snow awning"]}},
  {"id": "m-wandering-oasis", "style": "mystery", "title": "The Oasis That Moves at Night", "hook": "The only oasis in the Amber Expanse is a few steps farther east every morning, palms and all.", "twist": "The oasis isn’t running away. It’s following someone.", "open": "The caravan camp in the Amber Expanse wakes to find the oasis has wandered off again. {paces} east this time, pool and palm trees included.", "steps": ["Near {place} you find a line of damp sand running east, as if the pool had been poured, very slowly, across the dunes.", "{helper} mentions an old camel who leaves camp each night to hum by herself under the stars.", "The palm trees lean slightly east too, their fronds turned like ears toward something far off.", "Out on the dunes past {landmark} you find a smooth hollow where someone has been lying, the sand still warm.", "You lie in the hollow and hear it: a {tune}, and deep below it, water moving to keep time.", "The old camel explains she hums to the oasis every night, and it has been creeping closer to hear her better."], "end": "The caravan moves the camel’s sleeping mat right beside the pool. She hums her {tune}, the oasis settles happily in place, and everyone drifts off.", "vars": {"paces": ["Twenty paces", "Thirty steps", "A camel’s length"], "tune": ["low, sweet tune", "slow lullaby", "rolling, rumbly hum"]}},
  {"id": "m-upward-hourglass", "style": "mystery", "title": "The Hourglasses That Fall Upward", "hook": "In the Amber Expanse, the sand in every hourglass has started trickling up instead of down.", "twist": "The sand isn’t floating. It’s being carried, grain by grain.", "open": "The timekeepers of the Amber Expanse are flustered. In every hourglass on every shelf, the sand is climbing politely from the bottom bulb to the top.", "steps": ["At {place} you peer closely at a glass and see the rising sand moving in tiny, orderly lines.", "The head timekeeper admits she recently refilled every glass with fresh {color} sand from the dunes beyond {landmark}.", "{helper} says {color} sand from those dunes is famous for one thing: the beetles that nest in it.", "You tip an hourglass on its side and a tiny beetle climbs out, carrying one grain like a very important parcel.", "In the top bulb, the beetles have built a neat sand city with towers, gates, and a flag made from {flag}.", "The beetle queen explains her colony was scooped up by mistake, so they’ve been climbing to build a new home at the top."], "end": "You and the timekeepers carry every glass back to the dunes and gently tip the cities out. The beetles wave their flags, and the timekeepers buy plain sand from now on.", "vars": {"color": ["red", "golden", "rose-pink", "violet"], "flag": ["a single thread", "a scrap of silk", "a pressed petal"]}},
  {"id": "m-circle-of-bells", "style": "mystery", "title": "The Circle of Buried Bells", "hook": "Every caravan bell that went missing in the Amber Expanse has turned up buried in a perfect circle on the tallest dune.", "twist": "The bells weren’t hidden. They were arranged.", "open": "{count} caravans have lost their camel bells this month. This morning a guide found them all, buried to their brims in a perfect circle on the tallest dune.", "steps": ["Near {place} you find paw prints that turn in tight spirals, as if someone was spinning on their toes.", "{helper} says the bells only vanished on nights when the moon was nearly full.", "Inside the circle the sand is pressed flat and smooth, like a floor that has been swept with a tail.", "Each bell sits a single leap from the next, and when you hop from one to another, they chime a simple tune.", "Tucked beside the last bell is a feather and a note: “{note}”", "A desert fox admits she wanted a dance floor that plays music underfoot, and always meant to give the bells back."], "end": "The caravans lend their bells for one night and bring {drums} of their own. Under the full moon, everyone shares {snack} and dances around the fox’s circle.", "vars": {"count": ["Twelve", "Nine", "Eight"], "note": ["Practice. Full moon. Please come.", "Rehearsal at moonrise. Bring feet.", "Dance tonight. Everyone welcome."], "drums": ["drums", "tambourines", "clapping sticks"]}},
  {"id": "m-sinking-island", "style": "mystery", "title": "The Island That Sinks a Little Each Day", "hook": "One of the Starfall Isles is drifting lower every day, and nobody can find what’s pulling it down.", "twist": "Nothing is pulling the island down. Something that held it up has gone missing.", "open": "The island of {island} sits a bit lower in the sky each morning. The islanders measure it against the moon: a hand’s width yesterday, two today.", "steps": ["Near {place} you find a wisp of cloud snagged on a root beneath the island’s edge, soft and a little damp.", "{helper} remembers two plump clouds always drifted under {island} like pillows, but only one is there now.", "The remaining cloud sags under the island, looking thinner than yesterday and shivering in the breeze.", "Across the sky you spot a second cloud curled around a far island’s {mill}, turned away as if sulking.", "The keeper of the {mill} says that cloud arrived after a rumble of thunder a week ago and hasn’t budged since.", "The far cloud admits it quarreled with its partner over who got the sunny side, and floated off in a huff."], "end": "You broker a deal: sunny side on alternate days. The two clouds drift back together under {island}, and by {hour} the island is smug and level again.", "vars": {"island": ["Pebble Rest", "Thimble Isle", "Nook Rock", "Cobble Perch"], "mill": ["windmill", "weathervane", "bell tower"]}},
  {"id": "m-rain-falls-up", "style": "mystery", "title": "The Rain That Falls Up", "hook": "On one of the Starfall Isles, the rain has started falling upward, and the gardens are bone dry.", "twist": "The rain isn’t confused. Something underneath is thirstier than the gardens.", "open": "On Fernhold Isle the clouds gather, the rain begins, and every drop goes up. The gardeners stand under upturned umbrellas, catching nothing.", "steps": ["Near {landmark} you find a {can} hanging beneath the island’s edge, swinging gently, ivy tied round its handle.", "{helper} says the apprentice asked for “upside-down seeds” last month, and everyone laughed and gave him some anyway.", "Peering over the edge, you see roots pointing up and leaves hanging down: a whole garden planted on the island’s belly.", "A rope ladder beside the {can} leads down past a row of {crop} hanging like lanterns, each tied carefully to the rock.", "The apprentice is there, ringing a small {bell} so the clouds know where to send the water.", "He explains he wanted a garden of his own, and the only unused ground on Fernhold was underneath."], "end": "The head gardener climbs down, admires the upside-down {crop}, and teaches him to ring the {bell} only half the time. Rain falls both ways, and both gardens grow by {hour}.", "vars": {"can": ["watering can", "tin bucket", "copper jug"], "crop": ["pumpkins", "squashes", "melons"], "bell": ["rain-bell", "cloud chime", "cowbell"]}},
  {"id": "m-chimes-for-tamsin", "style": "mystery", "title": "The Wind Chimes That Call a Stranger", "hook": "Every wind chime on the Starfall Isles has started ringing the same name, and nobody here is called Tamsin.", "twist": "The name isn’t being called to someone. It’s being carried from someone.", "open": "The breeze across the Starfall Isles has a new habit. Every chime, on every porch, rings three notes that sound exactly like “Tam-sin.”", "steps": ["At {place} you find a chime with a thin {ribbon} tied to it, the ink smudged but the letter T still clear.", "{helper} says the tune started with the {wind}, which blows from the farthest isle, where hardly anyone lives.", "More of them flutter from chimes as you follow the {wind}, one letter each, spelling “FOR TAMSIN, FROM—” and then nothing.", "On the far isle stands a tiny cottage hung with dozens of chimes, all tuned by hand to the same three notes.", "Inside, a letter to Tamsin is pinned to the wall, its return address torn clean off by the wind.", "The cottage’s owner admits Tamsin was a pen pal who moved away, and the chimes were her way of sending hello on every breeze."], "end": "You find Tamsin in {village}, busy {hobby}. She writes back that same afternoon on a {ribbon}, and the chimes ring a brand-new name in reply.", "vars": {"ribbon": ["paper ribbon", "strip of sailcloth", "silk streamer"], "wind": ["west wind", "east wind", "north wind"], "hobby": ["learning to fly kites", "building a rowboat", "painting clouds"]}},
  {"id": "m-bridges-in-bows", "style": "mystery", "title": "The Bridges Tied in Bows", "hook": "Overnight, every rope bridge between the Starfall Isles has been tied into a big, neat bow.", "twist": "The bows aren’t pranks. They’re practice.", "open": "The rope bridges linking the Starfall Isles are still standing, but each one has a giant bow knotted in its middle. You can cross, if you duck.", "steps": ["At {place} you find a strand of {thread} wound through the rope, finer than hair and very strong.", "{helper} says each bow is a little neater than the last, as if someone is getting better at it.", "From the messiest bow to the neatest, you follow a trail of dropped spools of {thread} across the isles.", "On a lonely spire you find a web shaped like a box, with a gap in one side the size of a small gift.", "A tiny card is tucked in the web: “For {occasion}. Ribbon must be perfect.”", "A young sky-spider admits she needed practice tying bows, and the bridges were the only things big enough to learn on."], "end": "You bring her {ribbon} and help tie the finest bow in the Isles around Gran’s gift. The bridges come untied, and Gran shares {snack} at her party.", "vars": {"thread": ["silver thread", "pearl-white silk", "gossamer"], "occasion": ["Gran’s birthday", "Gran’s hundredth birthday", "Gran’s moving day"], "ribbon": ["a proper ribbon", "a length of velvet", "a roll of satin"]}},
  {"id": "e-river-that-comes-with-autumn", "style": "expedition", "title": "The River That Comes With Autumn", "hook": "A river runs through Mosswood only one week a year, and nobody has ever drawn where it goes.", "twist": "The river isn’t flowing to the sea at all; it’s flowing back to where it began.", "open": "The first red leaf fell this morning, and with it came the river, silver and new. You have a blank map, a pencil stub, and one week.", "steps": ["At {place} you make a small {boat} and set it on the current to see which way the river chooses.", "{critter} tells you the river bends around every tree that was planted by hand, never through.", "Your pencil runs short, so you start marking the map with {mark}, one color for each day.", "You find your {boat} circling in an eddy, patiently waiting for you to catch up.", "The river climbs a mossy slope it should not be able to climb, following old stepping stones toward {landmark}.", "At the top sits a spring in a stone bowl, and your {boat} is bobbing in it as if it arrived first."], "end": "Your map closes into a perfect loop of {mark}. You pin it up in {village}, and next autumn everyone knows where to set their boats.", "vars": {"boat": ["leaf boat", "acorn-cap boat", "bark boat", "twig raft"], "mark": ["pressed leaves", "dabs of berry ink", "bits of colored moss", "scraps of birch bark"]}},
  {"id": "e-message-for-the-youngest-tree", "style": "expedition", "title": "A Message for the Youngest Tree", "hook": "The oldest oak in Mosswood has one thing to tell the newest sapling, and the root paths have gone quiet.", "twist": "The sapling has been sending messages too; they just keep getting stuck in the same place.", "open": "The oldest oak hands you a {nut} with something scratched inside. The root paths that used to carry news are tangled, so this message goes on foot.", "steps": ["At {place} a ring of {glow} marks the first root path, glowing faintly where the news used to travel.", "{helper} draws you a map of the roots, though half of it is labeled only “probably.”", "You find a knot where three root paths meet, stuffed full of tiny notes that never got delivered.", "One note is from the sapling, asking the oak a question in shaky handwriting: “How do you stand so tall?”", "You untangle the knot, and the {glow} along every path begin to glow again, one after another.", "The sapling stands in a sunny clearing near {landmark}, leaning toward you as if it knew someone was coming."], "end": "You open the {nut} for the sapling. Inside, the oak’s answer reads, “{answer}” The roots hum, and the old notes start moving again.", "vars": {"nut": ["polished acorn", "speckled hazelnut", "glossy chestnut", "tiny beechnut"], "glow": ["mushrooms", "moss lamps", "toadstools", "bluebells"], "answer": ["Slowly, and with friends.", "One ring at a time.", "Roots first, then reaching.", "By holding on to good dirt."]}},
  {"id": "e-bridge-for-moving-day", "style": "expedition", "title": "A Bridge for Moving Day", "hook": "The hedgehogs of Mosswood move house tomorrow, and the only bridge across the brook washed away last night.", "twist": "The hedgehogs aren’t leaving for good; they plan to visit the old side every Sunday, so the bridge has to last.", "open": "Forty hedgehogs are packed and waiting, each with a {cup} tied to their back. Across the brook is their new home, and between here and there is only water.", "steps": ["Near {place} you find a spool of {yarn} yarn snagged on a bramble, far too long for anyone to have lost by accident.", "{helper} agrees to lend you planks, as long as you return the favor with a thank-you note for each one.", "You measure the gap with the {yarn} yarn and discover it is exactly {count} planks wide, if nobody wobbles.", "The eldest hedgehog admits she knitted the yarn herself, hoping someone would build the bridge she couldn’t.", "You lay the planks and lash each one with {yarn} yarn, tight enough that the {cup}s won’t even rattle.", "The first hedgehog tiptoes across, then the second, and soon a small parade is clinking over the water."], "end": "The last hedgehog ties a {yarn} bow on the railing. You write {count} thank-you notes for {helper}, and the hedgehogs share {snack} with you every Sunday.", "vars": {"yarn": ["red", "sky-blue", "sunflower-yellow", "plum-purple"], "cup": ["teacup", "thimble", "tiny kettle", "jam jar"], "count": ["nine", "eleven", "twelve", "seven"]}},
  {"id": "e-return-to-sender-by-sea", "style": "expedition", "title": "Return to Sender, by Sea", "hook": "A message in a bottle washed up on Tideglass Coast, and its writer is still waiting for a reply.", "twist": "The note is fifty years old, but whoever wrote it has kept sending a new bottle every single week.", "open": "The bottle is green, the cork is sealed with {wax} wax, and the note inside asks, “Is anyone out there?” A tiny {tower} is drawn in the corner.", "steps": ["At {place} {helper} squints at the {wax} wax and says only one shop on the coast ever sold that color.", "The wax shop is shut, but a sign in the window reads, “Gone to the {tower}, back by {hour}.”", "A crab with a shell full of sea glass trades you directions for {trinket}.", "You write a reply on the back of the note, “Yes, someone is,” and tuck it back inside the bottle.", "The {tower} comes into view, its lamp blinking in a pattern that looks a lot like hello.", "At the top, an old woman is sealing a fresh bottle with {wax} wax, and she looks up, surprised, at yours."], "end": "She reads your reply twice and laughs until the lamp shakes. You spend the evening sealing bottles together, each one saying, “Yes, someone is.”", "vars": {"wax": ["blue", "sea-green", "coral", "violet"], "tower": ["striped lighthouse", "crooked lighthouse", "lighthouse with a red cap", "lighthouse shaped like a candle"]}},
  {"id": "e-path-at-the-lowest-tide", "style": "expedition", "title": "The Path at the Lowest Tide", "hook": "Once a year the sea pulls back far enough to show a sandbar to the Glass Isle, and that night is tonight.", "twist": "The person who laid the first shells is still on the Glass Isle, hoping someone will finish the path.", "open": "The moon is full and the sea is shy, drawing back from Tideglass Coast inch by inch. Under the water is a path to the Glass Isle, and you have a pocket full of {shell} shells.", "steps": ["At {place} the first stretch of sandbar appears, rippled and firm, and you set a {shell} shell where it begins.", "{critter} tells you to walk only where the sand is striped, never where it’s smooth.", "Halfway out, you find a line of weathered shells already laid down, placed by someone years ago.", "The old shells end at a tidepool full of tiny {pool} who have been rearranging them for fun.", "You set your shells beside theirs, and the {pool} agree, grudgingly, to leave the new ones alone.", "The Glass Isle rises ahead, green and gleaming, its door propped open with a single {shell} shell."], "end": "The old shell-layer shares {snack} and a hand-drawn map. By morning the sea returns, but under it your {shell} shells hold the path for next year.", "vars": {"shell": ["white", "pink", "speckled", "pearly"], "pool": ["starfish", "hermit crabs", "sea snails", "periwinkles"]}},
  {"id": "e-clock-that-keeps-the-tide", "style": "expedition", "title": "A Clock That Keeps the Tide", "hook": "The harbor’s tide clock has come apart, and the fishing boats keep coming home to empty docks.", "twist": "The gulls only carried off the pieces because the clock’s loud ticking kept their chicks awake.", "open": "The harbormaster’s tide clock has been scattered by gulls and waves. Gather the pieces, rebuild it, and the boats will know when to come home.", "steps": ["At {place} you find the clock’s {float} wedged between two rocks, still bobbing hopefully.", "A gull admits to taking the clock hands, mostly because they looked like very shiny fish.", "The glass face turns up in a tidepool, where a family of {tenants} has been using it as a skylight.", "You trade the {tenants} {trinket} for a new roof, and they wave you off happily.", "Back at the harbor, the pieces fit, but the clock won’t start without something to tell it where the sea is.", "You tie the {float} to the clock on a long rope and lower it into the water, and under {weather} the hands begin to turn."], "end": "You tuck a scrap of {pad} inside so the clock ticks softly and the gull chicks sleep through it. At the next high tide, every boat comes home to a full dock in {village}.", "vars": {"float": ["brass float", "cork float", "copper buoy", "glass float"], "tenants": ["shrimp", "tiny crabs", "sea snails", "periwinkles"], "pad": ["felt", "sheep’s wool", "sailcloth"]}},
  {"id": "e-cog-at-the-top-of-the-tower", "style": "expedition", "title": "The Cog at the Top of the Tower", "hook": "The great clock of the Clockwork Ruins is missing one small cog, and it’s sitting in your pocket.", "twist": "The stairs aren’t broken; they’ve been spinning to keep the clock’s gears from rusting while it waited.", "open": "{helper} hands you a cog no bigger than a coin, with a small {mark} engraved on one tooth. It belongs at the top of the great clock tower, where the stairs never stand still.", "steps": ["At {place} the tower door swings open on its own, as if it heard a cog jingling in a pocket.", "The spiral stairs turn slowly, so you learn to hop to each step when it lines up with the one above.", "{critter} who lives in the gears shows you a shortcut through the {room}, if you time it right.", "You pass a gallery of old clock faces, each stopped at a different hour, every one of them pointing upward.", "The stairs slow as you climb, and the higher gears creak as if they are leaning in to see.", "At the very top, a single empty axle waits, polished and bright, with a {mark} painted beside it."], "end": "The {mark} cog clicks into place, and the whole tower sighs into motion. The stairs finally hold still, and by {hour} the great clock rings for the first time in years.", "vars": {"mark": ["star", "crescent moon", "tiny key", "leaf"], "room": ["pendulum room", "spring cellar", "bell loft", "gear gallery"]}},
  {"id": "e-map-of-moving-hallways", "style": "expedition", "title": "A Map of Hallways That Move", "hook": "The halls of the Clockwork Ruins rearrange themselves every hour, and the librarian hidden inside needs a map.", "twist": "The halls follow the {player}’s tune, and someone has been winding it backward.", "open": "Deep in the ruins, a patient librarian keeps books for anyone who can find her. Your job is to draw a map of halls that won’t stay put.", "steps": ["At {place} you {tag} on the wall and wait, and on the hour the mark slides quietly to the left.", "{critter} explains that every hall moves one turn at a time, like hands on a very large clock.", "You sketch the halls in rings instead of rows, and the map finally starts to make sense.", "A {player} on a shelf plays a tune whenever the halls shift, and its notes match the turns.", "You hum the tune as you walk and reach each doorway just as it swings into place.", "The last hall opens onto a round room stacked with books and one very surprised librarian."], "end": "The librarian winds the {player} the right way and pins your ring-shaped map by the door. Now visitors hum their way in, and she has company until {hour} most days.", "vars": {"tag": ["chalk an arrow", "chalk a star", "pin a ribbon", "stick a paper tag"], "player": ["music box", "wind-up bird", "clockwork flute", "tin carousel"]}},
  {"id": "e-tea-for-the-tin-gardener", "style": "expedition", "title": "Tea for the Tin Gardener", "hook": "A clockwork gardener tends {bloom} at the far end of the ruins, and nobody has brought them tea in a hundred years.", "twist": "The gardener never drank the tea; they poured it on the {bloom}, which is why they are still waiting too.", "open": "The rail cart that once carried tea across the Clockwork Ruins is rusted to its track. You have a teapot, a basket, and a feeling someone is waiting.", "steps": ["At {place} you find the old rail cart, its brakes stuck and a faded tea ring on its seat.", "{helper} trades you a tin of oil for a promise to bring back the teapot’s lid when you’re done.", "With oiled wheels, the cart rattles forward past {landmark}, through a hall of sleeping machines.", "A switch on the track is jammed, and you nudge it free with the teapot spout, very gently.", "The garden appears, overgrown and brilliant, with all the {bloom} leaning down the track toward you.", "The tin gardener stands among the {bloom}, holding out an empty cup as if they never stopped hoping."], "end": "You pour one cup for the gardener and one for the {bloom}. On the ride home you return the lid to {helper}, and now the cart runs every {day}.", "vars": {"bloom": ["roses", "tulips", "peonies", "sunflowers"], "day": ["Thursday", "Sunday", "Tuesday", "Saturday"]}},
  {"id": "e-train-that-stopped-halfway", "style": "expedition", "title": "The Train That Stopped Halfway", "hook": "A little clockwork train full of wind-up passengers has stood still in the ruins for years, halfway to the station.", "twist": "The train didn’t break down; it stopped to wait for one passenger who missed it.", "open": "The ticket clerk at the ruined {village} station still sells tickets until {hour}, just in case. She gives you a {metal} winding key and points down the rusty track.", "steps": ["At {place} you find the train’s engine, dusty and patient, with a keyhole shaped exactly like your {metal} key.", "The wind-up passengers inside are frozen mid-wave, each holding a ticket stamped for the same day.", "{critter} shows you where the rails are bent, and how to coax them straight with a lever.", "One seat in the front car is empty, with a ticket tucked under the cushion and a tiny {wrap} beside it.", "Halfway back, you find a wind-up {rider} on a bench by the track, shivering a little, with no {wrap}.", "You carry the {rider} to the empty seat and wrap the tiny {wrap} around its neck, and the whole car seems to relax."], "end": "You turn the {metal} key, and the train chugs the rest of the way with every passenger waving. The ticket clerk stamps their tickets at last and cries a little, happily.", "vars": {"metal": ["brass", "silver", "copper", "bronze"], "rider": ["rabbit", "duckling", "mouse", "bear cub"], "wrap": ["scarf", "muffler", "neckerchief"]}},
  {"id": "e-one-spark-for-the-hollows", "style": "expedition", "title": "One Spark for the Hollows", "hook": "The Great Lantern of Lantern Hollows has gone out, and the only spark left is dozing in a {box}.", "twist": "The spark isn’t sleepy at all; it’s shy of the very dark it’s supposed to light.", "open": "{helper} presses a {box} into your hands. Inside, a spark the size of {size} is curled up, and the Great Lantern waits at the bottom of the hollows.", "steps": ["At {place} the {box} grows warm when you walk toward the deeper tunnels and cool when you turn back.", "A family of glowworms lights the first stretch of path, but they only reach as far as {landmark}.", "You hum a little to the {box}, and the spark peeks out, flickering in time.", "{critter} shares a pocket of {bedding}, soft enough to make the spark a tiny bed.", "The tunnels open onto a vast cavern, and in the middle stands the Great Lantern, cold and patient.", "You open the {box} beside the lantern, and the spark climbs out onto the {bedding}, brave and bright."], "end": "The spark leaps into the wick, and warm gold light pours across the cavern. The glowworms cheer, and the spark finally has more light than it could ever be shy of.", "vars": {"box": ["matchbox", "tinderbox", "snuffbox", "walnut shell"], "size": ["a ladybug", "a raisin", "a pea", "a button"], "bedding": ["dry moss", "thistledown", "dandelion fluff", "lamb’s wool"]}},
  {"id": "e-lake-counted-in-drips", "style": "expedition", "title": "The Lake Counted in Drips", "hook": "The well in {village} is running low, and the answer is somewhere on the unmapped lake beneath Lantern Hollows.", "twist": "The blockage isn’t an accident; someone built it on purpose, and they had a very good reason.", "open": "{helper} suspects the lake under the hollows has stopped feeding the village well. You take a {cup}, a lantern, and a borrowed rowboat.", "steps": ["At {place} you set the {cup} under a dripping stalactite, count how fast it fills, and mark it on your map.", "A very polite cave fish tells you the lake is shaped like a {shape} and always has been.", "The drips grow faster as you row toward the narrow end of the {shape}, and your map fills with marks.", "You find pebbles and driftwood blocking a channel, stacked neatly, like somebody’s front wall.", "Behind the wall lives a family of {dwellers} who built it to keep the current from rocking their cradles.", "Together you shift the wall a little to one side, so the family stays snug and the water flows again."], "end": "Water hums toward the village well, and the {dwellers} keep their calm pool. You give {helper} your map, and the {cup} stays behind as their new bathtub.", "vars": {"cup": ["tin cup", "chipped teacup", "copper mug", "acorn bowl"], "shape": ["keyhole", "teardrop", "crescent", "pear"], "dwellers": ["cave newts", "blind shrimp", "pale crayfish", "glow snails"]}},
  {"id": "e-window-for-the-deep-garden", "style": "expedition", "title": "A Window for the Deep Garden", "hook": "Deep in Lantern Hollows grows a garden that has never seen the sun, and its gardener would love to show it.", "twist": "The {bloom} glow on their own, and Mistle worries that sunlight might make them stop.", "open": "Old Mistle the mole grows mushrooms and {bloom} far below the hills. She has a hand-drawn plan for a skylight and a very long list of things to bring.", "steps": ["At {place} you find the first thing on Mistle’s list, a {pane} tucked in a rockslide.", "A family of bats agrees to carry rope, but only after dark, which down here is all the time.", "You trace the hill above to the spot near {landmark} where a single root pokes through, right over the garden.", "{helper} lends you a chisel and some advice: cut slowly, and the hill won’t mind.", "You carve a small round hole, set the {pane} in place, and seal it with clay from the garden.", "A beam of daylight drops through the pane like a ribbon, and the {bloom} turn to look."], "end": "The {bloom} open in daylight, pale and astonished, and when evening comes they still glow. Mistle sets a chair under the window and declares the list finished.", "vars": {"bloom": ["moonflowers", "glow lilies", "starbells", "lantern poppies"], "pane": ["round pane of glass", "ship’s porthole", "lens from a lighthouse", "disc of sea glass"]}},
  {"id": "e-boardwalk-to-the-frog-concert", "style": "expedition", "title": "A Boardwalk to the Frog Concert", "hook": "The frogs of Whisperfen hold one grand concert a year, on an island no audience has ever reached.", "twist": "The frogs are thrilled to have an audience, but a few of them have terrible stage fright.", "open": "Every midsummer the frogs of Whisperfen sing on {isle} while everyone listens from far away. This year they’ve sent an invitation, and a request for a boardwalk.", "steps": ["At {place} you find a stack of {wood}, damp but sturdy, perfect for walking on.", "{helper} shows you how to lay {wood} across tussocks so they float without sinking.", "The marsh gets deeper, and you tie cattails to each board so none of them drift away at night.", "A frog in a tiny {outfit} hops over to inspect your work and croaks a very serious approval.", "You run out of {wood} just short of {isle}, with a small gap of open water left over.", "The frog in the {outfit} explains that the gap is perfect: close enough to hear, far enough to feel brave."], "end": "You finish the boardwalk with a wide platform right at the edge of the gap. That night, under {weather}, the whole marsh gathers there, and the frogs sing the best concert of their lives.", "vars": {"wood": ["barrel staves", "old oars", "fence boards", "driftwood planks"], "isle": ["Lily Island", "Toadstool Isle", "Reed Rock", "Cattail Key"], "outfit": ["bowtie", "top hat", "velvet cape", "monocle"]}},
  {"id": "e-where-the-fog-is-made", "style": "expedition", "title": "Where the Fog Is Made", "hook": "Every morning fog rolls out of the middle of Whisperfen, and no one has ever mapped the way to where it starts.", "twist": "The handwriting on the note looks exactly like the postmaster’s, only much younger.", "open": "Mail boats keep getting lost in the Whisperfen fog. The postmaster gives you a compass, a coil of {line}, and a request: find where the fog begins and draw the way back.", "steps": ["At {place} you tie your {line} to a post and start unspooling, so the way back is never in doubt.", "{critter} tells you the fog smells faintly of {scent} the deeper you go.", "The fog thickens into soft white lanes between the reeds, and you sketch each one as you pass.", "You hear a gentle, steady whistle ahead, like a kettle that has been patient for a very long time.", "In a small clearing past {landmark} sits a mossy cottage, its chimney puffing out {scent} fog.", "Inside, a kettle bubbles on the stove, and a note beside it reads, “{note}”"], "end": "You follow your {line} home, and the postmaster turns pink. Together you go back, pour two cups, and turn the kettle down low, so the fog stays soft and the boats find their way.", "vars": {"scent": ["peppermint", "chamomile", "cinnamon", "lemon balm"], "line": ["string", "red thread", "fishing line", "kite twine"], "note": ["Back in five minutes.", "Just popped out.", "Gone for more honey.", "Kettle on, back soon."]}},
  {"id": "e-library-that-floats", "style": "expedition", "title": "The Library That Floats", "hook": "High water has cut off the villages of Whisperfen, and the only books left are on a raft that needs someone to steer it.", "twist": "The missing page wasn’t lost; a young reader borrowed it to find out the ending first.", "open": "The floating library is a raft stacked with books, a striped awning, and a bell. The librarian’s knee is sore, so the pole is yours this week.", "steps": ["At {place} you ring the bell, and a line of eager readers wades out to swap books and news.", "One favorite book, {book}, is missing its final page, and every reader who returns it sighs at the ending.", "A family of {paddlers} offers to nudge the raft through channels where your pole can’t reach the bottom.", "In {village}, {helper} trades you a rainproof blanket to keep the books dry.", "The channels narrow and wind, but the {paddlers} know every turn by heart.", "The last village waits on stilts, and a small reader on a porch is holding a single folded page."], "end": "The small reader hands back the page, and you read the end of {book} aloud to the whole village. Everyone cheers, and the raft sails home with its favorite book complete again.", "vars": {"book": ["The Moth Who Sailed", "Twelve Brave Turnips", "The Kettle Knight", "A Pocketful of Weather"], "paddlers": ["turtles", "otters", "beavers", "ducks"]}},
  {"id": "e-seed-for-the-snowy-summit", "style": "expedition", "title": "A Seed for the Snowy Summit", "hook": "One seed can only grow at the top of Frostbell Pass, and it needs to get there before it gets cold feet.", "twist": "The seed isn’t meant to survive the snow; it’s meant to melt a little of it.", "open": "The seed is {look}. {helper}, who gave it to you, says it will sprout only on the summit, and only if it stays warm on the way.", "steps": ["At {place} you tuck the seed into your mitten, where it hums faintly like a cat in a sunbeam.", "{critter} in a knitted scarf points the way to the summit, past the {fall}.", "The wind picks up and the seed grows cooler, so you wrap it in your own scarf and walk faster.", "A family of {family} lets you warm up in their den, and the seed glows brighter by their hearth.", "Above the {fall} the path turns to ice, and you follow old footprints someone left on purpose.", "At the summit you find a small circle of bare earth, melted clear, waiting for exactly one seed."], "end": "You plant the seed, and a green shoot rises, warming the snow around it into a tiny meadow. You share {snack} with the {family} in the summit’s first spring.", "vars": {"look": ["small, round, and warm as a teacup", "pale gold and warm as toast", "speckled and warm as a sunny pebble"], "fall": ["frozen waterfall", "icicle cliff", "glacier stair"], "family": ["snow hares", "marmots", "snow foxes"]}},
  {"id": "e-soup-for-the-hermit", "style": "expedition", "title": "Soup for the Hermit on the Hill", "hook": "A hermit high in Frostbell Pass has caught a cold, and the village soup has to reach them while it’s still hot.", "twist": "The hermit isn’t alone; they’ve been sheltering every lost traveler on the pass all winter.", "open": "The cook in {village} ladles her best {soup} into a big {pot} with a tight lid. The hermit’s cabin is three switchbacks up, and the soup starts cooling the moment you step outside.", "steps": ["At {place} {helper} warms the {pot} by a forge, just long enough to buy you an extra hour.", "A badger with a snow shovel clears the first switchback and warns that the second has a mind of its own.", "The second switchback keeps drifting shut, so you follow the {markers} the hermit set out last fall.", "A frozen bridge creaks under you but holds, and the pot lid rattles like it’s cheering.", "You spot a column of chimney smoke ahead, and the pot is still warm against your hands.", "The hermit opens the door with a sniffle, and behind them sit five travelers around one very small pot."], "end": "The {pot} is big enough for everyone, and the soup is still steaming. The hermit sneezes, laughs, and asks you to stay, and by the fire the cabin feels like a village of its own.", "vars": {"soup": ["barley soup", "pumpkin stew", "leek-and-potato soup", "mushroom broth"], "pot": ["copper pot", "iron cauldron", "enamel stockpot"], "markers": ["red flags", "ribbon-tied poles", "painted stones"]}},
  {"id": "e-bells-of-the-high-road", "style": "expedition", "title": "The Bells of the High Road", "hook": "The old road over Frostbell Pass is marked by bells, and half of them have gone quiet under the snow.", "twist": "The bells aren’t only markers; they were hung to play a tune, and one note has always been missing.", "open": "The pass warden gives you a small {metal} bell and a request: find every bell on the high road, ring it, and mark it on her map, so travelers never lose the way.", "steps": ["At {place} you brush snow off the first bell, ring it, and hear a clear note roll across the valley.", "{critter} shows you where the second bell hides, under a drift shaped like {drift}.", "Each bell rings a different note, and you jot each one beside its mark on the warden’s map.", "Read in order, the notes make the start of the tune the warden hums while she works.", "Near the top, by {landmark}, one bell post stands empty, its hook shining as if it has been waiting.", "The small {metal} bell in your pocket fits the empty hook exactly, and its note finishes the tune."], "end": "You ring the whole road from top to bottom, and the tune carries all the way down to the warden’s door. From then on, travelers hum it to find their way over the pass.", "vars": {"metal": ["silver", "glass", "copper", "brass"], "drift": ["a sleeping bear", "a giant loaf", "a curled-up cat", "an upside-down boat"]}},
  {"id": "e-cake-across-the-amber-expanse", "style": "expedition", "title": "A Cake Across the Amber Expanse", "hook": "A wedding at the far oasis needs its cake, and between here and there is a whole desert of sunshine.", "twist": "The top tier is meant for the camel who introduced the couple, and it’s now missing its {deco}.", "open": "The baker’s cake is three tiers tall, frosted in {flavor}, and a little nervous about the heat. You have a wagon, a {shade}, and until {hour}.", "steps": ["At {place} you tilt the {shade} over the cake and find it shades every tier, if you hold it just so.", "{critter} points out a route that follows every shadow in the desert.", "You rest the wagon in the shade of {landmark}, and the frosting firms up again in the cool shade.", "A dust devil spins by and nearly takes the parasol, but it only steals a single {deco}.", "The oasis palms appear on the horizon, and the cake has not slumped even a little.", "At the wedding, a camel wearing a flower crown sniffs the cake and looks very hopeful."], "end": "A gentle breeze drops the stolen {deco} right back on the top tier. The couple cuts the first slice for the camel, and your {shade} shades the party until {hour}.", "vars": {"flavor": ["lemon", "rosewater", "honey", "vanilla"], "deco": ["sugar flower", "marzipan bird", "candied rose", "chocolate star"], "shade": ["striped parasol", "paper umbrella", "lace parasol", "patchwork umbrella"]}},
  {"id": "e-oasis-that-wanders", "style": "expedition", "title": "The Oasis That Wanders", "hook": "The Amber Expanse’s only oasis moves a little every night, and the caravans need a map that can keep up.", "twist": "The oasis isn’t running away; it’s following a star nobody ever put on the map.", "open": "{helper} unrolls a map of crossed-out oases, each one a night too late, and hands you a star chart to work out where the water goes.", "steps": ["At {place} you find the oasis’s last known spot, now dry, with a ring of wet footprints leading east.", "A {friend} who naps under the dunes says the oasis always leaves right after the evening star rises.", "You compare the footprints to your star chart and see the oasis follows one bright point across the sky.", "A corner of your chart is smudged, and the star the oasis follows isn’t drawn on it at all.", "You wait up with the {friend}, and at midnight you see it: a small new star, {twinkle}, just above the dunes.", "The oasis sits right beneath it, palms and all, looking relieved that someone finally noticed."], "end": "You add the new star to the chart, and {helper} draws the oasis’s path beside it. Now the water waits every night, and the {friend} shares {snack} with each caravan.", "vars": {"friend": ["fennec fox", "sand cat", "jerboa", "horned lizard"], "twinkle": ["blinking", "faintly green", "rosy pink", "barely flickering"]}},
  {"id": "e-rain-in-a-jar", "style": "expedition", "title": "Rain in a Jar", "hook": "A cloud gave you one jar of rain, and a garden in the middle of the Amber Expanse has been waiting all year for it.", "twist": "The jar isn’t running dry in the heat; the little cloud inside keeps making more rain, one drop at a time.", "open": "The jar is cool to the touch, and inside it a small {cloud} cloud drizzles on itself. {helper} gardens {dist}, and the sprouts there are thirsty.", "steps": ["At {place} you notice a tiny pinhole in the jar’s lid, and a single drop escapes whenever you stop walking.", "{critter} follows the trail of drops and asks, politely, if you might linger a while.", "A sandy wind picks up, and you shelter behind {landmark}, cradling the jar so the cloud doesn’t tumble.", "On a ridge you pass a line of green specks, sprouting exactly where drops from the jar fell.", "The garden plot appears, fenced with driftwood, every sprout leaning toward the jar.", "{helper} opens the lid, and the tiny cloud floats out, surprised to find so many friends below."], "end": "The cloud rains gently over the garden, and a green trail now leads back the way you came, drop by drop. {helper} sets the jar on a post, and the cloud comes home to it each evening.", "vars": {"cloud": ["gray", "silver", "lavender", "pearl-white"], "dist": ["three dunes east", "past the salt flats", "beyond the red rocks", "over two tall dunes"]}},
  {"id": "e-staircase-to-a-crooked-star", "style": "expedition", "title": "The Staircase to a Crooked Star", "hook": "One star over the Starfall Isles is hanging crooked, and the only way up is a staircase of floating islands.", "twist": "The star didn’t come loose by accident; it leaned over to watch the festival below.", "open": "A stargazer hands you a wrench shaped like a {w}. Above the Starfall Isles one star is tipped sideways, and every night the {flyers} fly in circles around it.", "steps": ["At {place} the first floating island bobs low enough to step onto, and the next drifts over like a polite elevator.", "{helper} lends you a rope of braided mist for the gaps between the higher islands.", "Each island is smaller than the last, until you are hopping between rocks no bigger than pillows, with {critter} for company.", "From up here you can see a {fest} on the isles below, and the crooked star is leaning toward it.", "The final island holds a tiny workshop with a telescope pointed not at the sky, but down.", "The star hangs within reach, one golden bolt loose, exactly the size of your {w}-shaped wrench."], "end": "You tighten the bolt, and the star straightens with a pleased twinkle. You aim the telescope at the festival for it, and the {flyers} below fly home in happy, straight lines.", "vars": {"w": ["crescent moon", "comet", "fish", "teardrop"], "fest": ["lantern festival", "kite festival", "dumpling festival", "paper-boat parade"], "flyers": ["moths", "fireflies", "night swallows"]}},
  {"id": "e-kite-post-of-starfall", "style": "expedition", "title": "The Kite Post of Starfall", "hook": "The kite mail between the Starfall Isles has stopped, and a bag of letters is waiting for a pilot.", "twist": "The kite post didn’t stop because of a storm; the winds were simply worn out.", "open": "The postmaster’s kite is {kite}, and the mailbag is stuffed. On top sits one letter with no name at all, only a drawing of a windmill.", "steps": ["At {place} you launch the kite, and the mailbag lifts you gently from one island to the next.", "{critter} takes the small letters to the small islands while you handle the parcels.", "A gust carries you off course toward an island you’ve never seen, crowded with windmills.", "The windmills are still, and a sign on the biggest one reads, “{sign}”", "You find the winds curled up like cats in the windmill loft, worn out from carrying everyone’s mail.", "The drawing on the nameless letter matches this windmill exactly, so you slide it under the loft door."], "end": "The winds open a thank-you card signed by every island, and stretch awake, refreshed. By {hour} kite mail flies again from {village}, and now each bag carries one extra letter addressed to the wind.", "vars": {"kite": ["patched but proud", "striped like a candy", "shaped like a big fish"], "sign": ["Closed for resting. Wind is very tired.", "Nap in progress. Please do not gust.", "Winds asleep. Back when rested."]}},
  {"id": "e-bridge-between-two-islands", "style": "expedition", "title": "A Bridge Between Two Islands", "hook": "Two friends on neighboring Starfall Isles have waved to each other every day for years and never once met.", "twist": "Both friends have been building half a bridge in secret, and neither half quite reaches.", "open": "A shy lamplighter on one island and a potter on the next wave across the gap every evening. The lamplighter asks for help building a way across and hands you a spool of {thread} thread.", "steps": ["At {place} you tie the {thread} thread to a post and let the breeze carry the loose end across the gap.", "A flock of cloud sheep offers their wool, fluffy enough to walk on if it’s packed tight around the thread.", "You spin cloud wool along the thread, and under {weather} a narrow, springy path begins to stretch across the sky.", "Halfway across, you find another path already there, made of {tile}, stopping in midair.", "You weave the cloud wool into the {tile}, and the two halves hold together like an old handshake.", "The path reaches the far island, and the potter comes running, dusty with clay and carrying a teapot."], "end": "The lamplighter and the potter meet in the middle of the bridge and share {snack} with you. They still wave every evening, only now from much closer, and the {thread} thread glows at dusk.", "vars": {"thread": ["silver", "golden", "moonlight-blue", "rose-gold"], "tile": ["glazed clay tiles", "painted saucers", "terracotta bricks"]}},
  {"id": "v-wedding-cake-that-wandered", "style": "rescue", "title": "The Cake That Left the Bakery", "hook": "A {cake} has hopped off its stand in {village}, and the wedding starts at sundown.", "twist": "The cake isn’t fleeing the wedding; it’s trying to reach the groom’s grandmother, who can’t make the walk.", "open": "The bakery door is open, the cake stand is empty, and a trail of {trail} leads out into {place}.", "steps": ["Near {landmark} you find the {topper}, set upright on a fencepost as if to watch the road.", "{helper} explains the recipe came from the groom’s grandmother, and cakes made with love get ideas.", "More {trail} dot the gate of the old orchard, where the path climbs toward the cottages on the hill.", "{critter} watches you from an apple tree, right above a cake-shaped dent in the grass.", "At the top of the hill, a porch light is on, and a rocking chair faces the valley where the wedding will be.", "You find the {cake} on the porch table, perfectly whole, and the grandmother holding a fork."], "end": "You carry the grandmother, the cake, and the {topper} down the hill in a borrowed cart. She cuts the first slice at sundown, and nobody minds that it’s travelled.", "vars": {"cake": ["three-tier lemon cake", "towering carrot cake", "rose-and-honey sponge", "four-tier almond cake"], "trail": ["sugared violets", "candied orange peels", "crushed meringues", "silver sugar pearls"], "topper": ["little sugar couple", "pair of marzipan doves", "tiny silver bell topper"]}},
  {"id": "v-scarecrow-on-holiday", "style": "rescue", "title": "The Scarecrow Who Took a Day Off", "hook": "The garden scarecrow of {village} has walked off to the seaside, and the crows are planning a feast.", "twist": "The crows have been guarding the garden themselves, out of respect for their old friend.", "open": "{scarecrow} the scarecrow is gone from his post in {place}, leaving a {hat} and a note: “Back soon (maybe).”", "steps": ["You find a single straw boot near {landmark}, laced neatly, like it was left to show the way.", "{helper} admits she never once thanked {scarecrow} in forty summers of standing in the {crop}.", "A postcard pinned to the market board shows the pier, signed with a crooked straw X.", "At the pier, the ice cream seller says a lanky fellow bought a cone and stared at the waves for an hour.", "{scarecrow} is on a bench with his other boot off, sand between his straw toes, looking happier than ever.", "He only wanted to see something besides {crop}, and he’ll go home if someone asks nicely."], "end": "You hand {scarecrow} his {hat} and a thank-you note in big letters. He goes home with sand in his pockets, and now he gets a seaside day every August.", "vars": {"scarecrow": ["Old Tom", "Uncle Barley", "Sir Stubble", "Ned Haystack"], "hat": ["straw hat", "battered bowler", "patched sunbonnet", "moth-eaten top hat"], "crop": ["cabbages", "turnips", "runner beans", "sunflowers"]}},
  {"id": "v-cloud-caught-on-steeple", "style": "rescue", "title": "The Rain Cloud on the Steeple", "hook": "The garden show is in three days, and the only rain cloud in the county is stuck on the {village} steeple.", "twist": "The cloud isn’t stuck at all; it’s afraid of raining on the bunting and ruining the show.", "open": "Every garden in {place} is thirsty, and one small grey cloud hangs from the steeple’s {vane} like a snagged balloon.", "steps": ["From the square you spot a string of {bunting} wound around the cloud, flapping every time it tries to drift.", "{helper} lends you a long hook pole, meant for the high windows, that might just reach.", "The flower judges admit they hung the bunting extra high this year so everyone could see it from the lane.", "From the belfry ledge, the cloud feels cool and nervous, and it shrinks back from the bright flags.", "The children bring buckets of their own to show the cloud where rain would be welcome.", "You tell the cloud the bunting can come down for an evening, and the {flowers} need it more than the flags."], "end": "You unhook the bunting and the cloud drifts over the gardens, raining just where the buckets were. The show opens on damp, happy {flowers}, and the flags go back up after.", "vars": {"vane": ["iron weathercock", "copper fish vane", "gilded arrow", "tin rooster"], "bunting": ["paper festival bunting", "striped cotton pennants", "gingham flags"], "flowers": ["roses", "sweet peas", "dahlias", "marigolds"]}},
  {"id": "v-tune-down-the-well", "style": "rescue", "title": "The Tune That Fell Down the Well", "hook": "The fiddler’s favorite {dance} tune fell into {landmark}, and the barn dance is tonight.", "twist": "The tune has been happily keeping the well water sweet, and it hesitates to leave.", "open": "{fiddler} played her {dance} too close to the edge, and the melody slipped off her strings into the water of {place}.", "steps": ["Leaning over {landmark}, you hear the tune faintly, bouncing off the stones a few notes at a time.", "{helper} lowers a bucket and pulls up only the first bar, which hops out and runs circles on the cobbles.", "{fiddler} says tunes like to be sung to, not fished for, and hums you the start so you can call it.", "You find the ladder into the old shaft, where moss grows in the shape of a treble clef.", "At the waterline the rest of the tune is swirling, and the water tastes brighter than you remember.", "You hum the first bar you caught earlier, and the rest of the {dance} perks up to listen."], "end": "The tune climbs back onto {fiddler}’s fiddle and promises to visit the well every Sunday. The barn dance runs late, and the water stays sweet all year.", "vars": {"fiddler": ["Old Wren", "Granny Pell", "Auntie Rook", "Mistress Hartley"], "dance": ["jig", "reel", "hornpipe", "polka"]}},
  {"id": "v-maypole-ribbons-loose", "style": "rescue", "title": "The Maypole Ribbons Ran Away", "hook": "The maypole’s ribbons in {village} have unwound themselves and tied the whole village in bows.", "twist": "The ribbons aren’t being mischievous; each one wants to be danced by a particular person.", "open": "On May morning, the maypole in {place} stands bare, and ribbons loop around chimneys, lampposts, and {critter}.", "steps": ["A {first} ribbon has tied the baker’s door to the tailor’s, and neither opens until someone unknots it.", "The schoolteacher counts: eight ribbons, but one {last} ribbon is missing entirely.", "Each ribbon, once freed, drifts toward a different house, like a dog waiting at a front door.", "{helper} remembers that every ribbon was first cut from a neighbor’s best clothes.", "You find the {last} ribbon in a window box, outside a house where a new family moved in last week.", "The new family’s daughter says nobody has asked her to dance the maypole yet."], "end": "Every ribbon goes back to the hand of the house it chose, the {last} one to the new girl. The dance begins late, a little tangled, and everyone laughs.", "vars": {"first": ["bright red", "sunflower yellow", "sky blue", "deep plum"], "last": ["pale green", "soft lilac", "peach-colored", "silvery grey"]}},
  {"id": "v-birthday-cards-on-wind", "style": "rescue", "title": "The Postbag and the Gale", "hook": "A gust has carried the postbag full of birthday cards across the rooftops of {place}.", "twist": "One card was never addressed at all, and it seems to be looking for someone on its own.", "open": "The letter carrier of {village} sits on the post office step with an empty satchel and {count} birthdays to deliver.", "steps": ["The first card is flapping in a hedge, still sealed, with a pressed {flower} under the stamp.", "The carrier points out the handwriting: half the cards were sent by the same shy person up the lane.", "Three more are stuck to the bakery window, held by a smear of honey from this morning’s buns.", "The weathervane shows the wind swinging round, carrying envelopes over the duck pond toward {landmark}.", "Near {landmark}, {helper} hands you a stack of cards and one blank envelope holding a pressed {flower}.", "The shy sender admits the blank one was for the carrier, who has never once received a birthday card."], "end": "You deliver all {count} cards and then one more, {flower} and all, into the carrier’s own hands. It’s her birthday tomorrow, and now the whole lane knows.", "vars": {"count": ["twelve", "nine", "fifteen", "eleven"], "flower": ["daisy", "violet", "buttercup", "forget-me-not"]}},
  {"id": "v-first-snowfall-in-jar", "style": "rescue", "title": "The First Snow in a Jar", "hook": "The {village} winter fair can’t open until the first snow falls, and someone has bottled it on a shelf.", "twist": "The snow asked to be kept; it was worried about landing on muddy ground.", "open": "It is the week of the winter fair and the sky over {place} is full, yet not a single flake has fallen.", "steps": ["In the curiosity shop window, a glass jar swirls white, labeled “First Snow, Handle Gently.”", "{helper} says a customer traded it for a spool of {thread} and promised to come back for it.", "The spool of {thread} turns up on the fair’s sledge rope, freshly knotted, beside a sign that says “Soon.”", "The sledge maker explains the hill has been nothing but mud since the autumn rains.", "Children spend the day laying {cover} over the hill so the snow will have a soft place to land.", "You bring the jar to the top of the prepared hill, and the snow inside presses gently against the glass."], "end": "You lift the lid, and the first snow spills over the {cover}, then the fields, then the rooftops. The winter fair opens by lantern light, and the sledges fly.", "vars": {"thread": ["silver thread", "gold embroidery silk", "blue darning wool", "red satin ribbon"], "cover": ["clean straw and linen", "old quilts and sheets", "sacks of fresh wood shavings"]}},
  {"id": "v-puppets-walked-off", "style": "rescue", "title": "The Puppets Who Missed Their Cue", "hook": "Every puppet in the traveling theatre has climbed out of the trunk an hour before showtime.", "twist": "The puppets want to rewrite the ending; they’re tired of the {beast} always losing.", "open": "The puppet trunk in {place} stands open and empty, and the puppeteer holds one empty glove that used to be the princess.", "steps": ["You find the {hero} puppet on the rim of {landmark}, practicing a bow, his wooden sword left behind.", "The puppeteer says the show has had the same ending for thirty years, and the {beast} gets the worst lines.", "Strings lead up a garden trellis to the attic of the inn, where tiny voices are arguing about a script.", "The innkeeper shares {snack} and says the puppets have been up there since noon.", "In the attic, the puppets have built their own stage from a hatbox, and the {beast} is the star.", "The {beast} puppet explains, in a small papier-mâché voice, it only wants an invitation to the final feast."], "end": "The puppeteer rewrites the last scene: the {beast} comes to dinner and the {hero} lends it his sword as a spoon. The crowd cheers louder than it has in thirty years.", "vars": {"beast": ["dragon", "sea serpent", "ogre", "giant"], "hero": ["knight", "woodcutter", "shepherd", "sailor"]}},
  {"id": "v-bread-oven-gone-cold", "style": "rescue", "title": "The Oven That Lost Its Warmth", "hook": "The bakery oven in {village} has gone cold for the first time in a hundred years, and the harvest loaves are due.", "twist": "The warmth didn’t go out; it went visiting, and it has been warming the whole street one house at a time.", "open": "Before dawn in {place}, {helper} opens the oven door to find it cold as a stone, and not even a spark will catch.", "steps": ["Soot footprints the size of mittens lead out of the oven door and across the flour-dusted floor.", "{helper} admits the oven has baked every day for a century without a single holiday.", "The {first_shop} says the shop was toasty all night, though nobody lit a fire.", "Next door, a cold kitchen was warm by breakfast, and {critter} is asleep in the empty grate.", "At the end of the street, you find the warmth curled up in the {last_stove}, glowing contentedly.", "The warmth likes being useful all over town, and it would stay if there were something for it at the bakery too."], "end": "You and {helper} agree the oven will rest every Sunday, when the warmth can go visiting. It glows home happily, and the harvest loaves come out golden.", "vars": {"first_shop": ["cobbler", "tailor", "potter", "candlemaker"], "last_stove": ["schoolhouse stove", "chapel boiler", "library’s iron stove", "inn’s kitchen range"]}},
  {"id": "v-doorstep-pies", "style": "mystery", "title": "The Pies on Every Doorstep", "hook": "Someone in {village} is leaving warm pies on doorsteps at night, and nobody can say who.", "twist": "Each pie is made from something the household thought they had lost.", "open": "Three mornings running, every house in {place} has woken to a warm {fruit} pie on the step, with a lattice crust and no note.", "steps": ["The pies are still warm at dawn, so whoever bakes them lives close, and bakes late.", "{helper} finds her pie holds fruit from the {fruit} tree she thought had died last spring.", "Flour dust on the doorsteps is finer than anything sold at the market, milled by hand.", "The old hand mill behind {landmark} has been cleaned and oiled, with fresh flour in its trough.", "A lattice pattern is scratched into a nearby bench, the same one on every crust.", "The retired {baker} confesses she can’t sleep, and baking keeps her company."], "end": "You bring the {baker} a {fruit} pie of her own, baked by the whole village together. She says it’s lumpy, then eats two slices, and now Thursday is pie night.", "vars": {"fruit": ["apple", "plum", "pear", "cherry", "quince"], "baker": ["schoolmistress", "midwife", "postmistress", "choir mistress"]}},
  {"id": "v-weathervane-points-one-way", "style": "mystery", "title": "The Weathervane That Won’t Turn", "hook": "The {village} weathervane points at the same cottage every day, no matter which way the wind blows.", "twist": "The cottage is empty, but the weathervane isn’t pointing at it; it’s pointing past it.", "open": "The {bird} on the town hall roof in {place} has faced the same {color} cottage for a week, even in a gale.", "steps": ["The {bird} isn’t rusted stuck; you can turn it by hand, and it swings right back like a compass needle.", "{helper} says the weathervane was forged from the old gate of a farm that used to stand nearby.", "The {color} cottage has been empty all summer, but its garden is freshly watered each morning.", "Behind the cottage, a narrow path runs straight in the {bird}’s direction, through a gap in the hedge.", "At the end of the path is an overgrown field and the stone posts of an old gate, empty of iron.", "The neighbor who waters the garden says her grandfather used to swing on that gate as a boy."], "end": "You help the neighbor hang a new little gate between the old posts. Next morning, the {bird} turns with the wind again, as though it was only homesick.", "vars": {"bird": ["iron rooster", "copper goose", "tin owl", "brass heron"], "color": ["little blue", "whitewashed", "rose-pink", "moss-green"]}},
  {"id": "v-gnomes-rearranged", "style": "mystery", "title": "Who Moves the Garden Gnomes?", "hook": "Every morning the garden gnomes on {lane} in {village} have swapped yards, and they look pleased about it.", "twist": "The gnomes aren’t moving themselves; they’re being carried to spell something out.", "open": "On {lane} in {place}, twenty painted gnomes have been rearranged overnight for the fifth night running.", "steps": ["The {gnome} is now on the doctor’s porch, and a tiny pair of footprints leads away through the dew.", "The footprints are too big for a gnome and too small for a grown-up: about the size of a child’s boots.", "Seen from {landmark}, the gnomes form rough letters across the lane, but the word isn’t finished.", "The letters so far read S, T, A, Y, and one more gnome is missing from its usual yard.", "The missing gnome turns up in a packing crate outside the house with the “For Sale” sign.", "A girl sitting on the crate admits her family is moving, and she wanted to leave the lane a message."], "end": "You help her finish the word: “STAY FRIENDS.” The whole lane signs her autograph book, and she takes the {gnome} to her new garden.", "vars": {"lane": ["Pudding Lane", "Thimble Row", "Buttercup Close", "Kettle Street"], "gnome": ["fishing gnome", "gnome with the wheelbarrow", "sleepy gnome", "gnome with the lantern"]}},
  {"id": "v-chalkboard-words-change", "style": "mystery", "title": "The Spelling Bee Chalkboard", "hook": "Someone keeps changing the words on the {village} spelling bee chalkboard, and the bee is on Friday.", "twist": "The changes aren’t pranks; each new word is a clue someone left for one particular speller.", "open": "The schoolhouse in {place} is locked every night, yet each morning the spelling list has new words chalked in.", "steps": ["Today’s list reads “{word_a}, {word_b}, courage,” none of which were on the original list.", "The chalk is a soft {chalk} brand nobody in the school uses; it’s sold only at the general store.", "{helper} sold one box last week, to the quiet boy who sweeps the schoolhouse after lessons.", "In the broom cupboard you find a notebook of words, each with a small drawing beside it.", "The drawings match the prize speller’s favorite things: {word_a}, {word_b}, and a sketch of a lion.", "The boy admits he only wanted her to get words she loved, because she freezes on the hard ones."], "end": "You tell the teacher, who keeps one of the boy’s words on the list: courage. On Friday the girl spells it perfectly and thanks the quietest boy in class.", "vars": {"word_a": ["marmalade", "gingerbread", "blackberry", "lemonade"], "word_b": ["lighthouse", "harmonica", "telescope", "accordion"], "chalk": ["yellow", "pink", "sky-blue", "lavender"]}},
  {"id": "v-maps-in-the-bread", "style": "mystery", "title": "The Bread With a Map in the Crust", "hook": "The {village} baker’s loaves have started coming out of the oven with tiny maps scored in the crust.", "twist": "The maps don’t lead to treasure; they lead to people who haven’t had fresh bread in a long time.", "open": "Every {loaf} in the bakery at {place} is marked with lines and little crosses, and the baker never touched a knife to them.", "steps": ["Laid side by side, the crusts show the same crooked lane from different angles, with a cross at the far end.", "The baker notices the maps only appear on loaves shaped by her new apprentice.", "The apprentice says he just hums while he kneads, an old {song} his mother taught him.", "The cross on the crust sits on a house past {landmark} that nobody visits much.", "Inside lives an old flour miller who can’t walk to market anymore and misses the smell of baking.", "He hums the same {song}: he taught it to the apprentice’s mother, years ago, in this very kitchen."], "end": "You carry the best {loaf} to the miller, and the apprentice comes too. Now the maps show only one cross, and it’s a delivery every morning.", "vars": {"loaf": ["round rye loaf", "braided milk loaf", "seeded cob", "crusty barley loaf"], "song": ["kneading song", "sea shanty", "harvest hymn", "skipping rhyme"]}},
  {"id": "v-board-game-acorn", "style": "mystery", "title": "The Acorn in the Game Box", "hook": "At game night, the {piece} is missing again, replaced by an acorn and a riddle.", "twist": "The riddles are written by the game itself, which wants to be played outdoors.", "open": "Game night at the inn in {place} is paused: the old wooden {game} is short one {piece}, and an acorn sits in its square.", "steps": ["The acorn is wrapped in a tiny note: “Where the board is green and the pieces grow.”", "{helper} says the {game} was carved from a single oak that stood by the green.", "On the green, a stump has been swept clean, and someone has chalked a board on top.", "{critter} scolds you from the hedge, sitting beside a chip of wood shaped like the {piece}.", "Under the stump’s roots you find the {piece}, dry and safe, tucked beside a row of sprouting acorns.", "The oldest player remembers they used to play here every summer before the tree came down."], "end": "The game resumes on the chalked stump, {piece} restored. Game night moves to the green for the summer, and a new oak sapling gets the best seat.", "vars": {"game": ["chess set", "draughts board", "backgammon set", "fox-and-geese board"], "piece": ["queen", "crowned king", "lucky die", "carved fox"]}},
  {"id": "v-piano-wrong-note", "style": "mystery", "title": "The Wrong Note at Evening", "hook": "Every evening the {village} hall piano plays one wrong note by itself, always a different key.", "twist": "The wrong notes aren’t mistakes; they’re a song, one note per night, for someone who is leaving.", "open": "The hall in {place} is empty after supper, yet each evening one sour note rings out from the piano.", "steps": ["You wait in the hall and hear it: a single clear {note}, though the lid is closed and the stool is empty.", "Inside the lid, a pencil list of notes and dates runs down the wood, older ones faded, new ones fresh.", "{helper} says the hammers have been adjusted from inside by very small, very careful hands.", "A family of mice lives in the piano’s back panel, with {stand} for a music stand.", "The notes, played together, are the start of a lullaby the old caretaker used to hum.", "The caretaker retires on Sunday, and the mice have been rehearsing her goodbye all month."], "end": "At the caretaker’s farewell tea, you lift the lid and the mice play the whole lullaby, every note right at last. She cries into her teacup and promises to visit.", "vars": {"note": ["B-flat", "high C", "F-sharp", "low G"], "stand": ["a thimble", "a bent hairpin", "a matchbox", "a folded bus ticket"]}},
  {"id": "v-honey-tastes-different", "style": "mystery", "title": "The Honey That Changes Flavor", "hook": "The {village} market’s honey tastes of a different flower every day, and some of those flowers don’t grow here.", "twist": "The bees aren’t travelling far; someone is growing a secret garden inside the town.", "open": "At the Saturday market in {place}, the honey tasted of {flavor_a} Monday, {flavor_b} Tuesday, and {rare} today.", "steps": ["{helper}, who keeps the hives, swears they never move and the bees never fly past the river.", "A bee on the stall carries a speck of bright {pollen} pollen, nothing like the meadow flowers.", "You follow a line of bees over the rooftops to a walled yard behind the post office.", "The postmaster admits he keeps a greenhouse full of seeds that came in letters from every corner of the world.", "Each packet was sent by his sister, a sailor, who writes from a new port every week.", "He’s been too shy to share the flowers, sure nobody would care about his odd little garden."], "end": "You help label the jars of {rare} honey “from the North.” The honey sells out by noon, and his sister gets a jar in the next letter.", "vars": {"flavor_a": ["lavender", "clover", "heather", "thyme"], "flavor_b": ["orange blossom", "jasmine", "lemon flower", "acacia"], "rare": ["snow roses", "frost lilies", "ice poppies"], "pollen": ["red", "violet", "copper", "turquoise"]}},
  {"id": "v-midsummer-soup", "style": "expedition", "title": "The Midsummer Soup", "hook": "The {village} midsummer soup needs one ingredient from every garden, and you are the one collecting.", "twist": "The last ingredient belongs to the grumpiest gardener in the village, who hasn’t shared in years.", "open": "The great soup pot in {place} is heating, and {helper} hands you a basket and a list with a name beside every item.", "steps": ["The first gardens give freely: carrots, a fistful of peas, and a single fat onion wrapped in a handkerchief.", "The list has one line crossed out and rewritten: “{herb}, from the corner house, ask kindly.”", "The allotments near {landmark} hand over potatoes and leeks, and gossip that the corner house grows the best {herb}.", "Up the hill, the goat farmer adds a wedge of {cheese} that isn’t on the list, “for luck.”", "The corner house gate is closed, but you can smell the {herb} from the lane, thick and warm.", "The old gardener opens the gate a crack and says nobody has asked him for anything in a very long time."], "end": "You ask kindly, and he gives you the {herb}, then walks to the square with you. The midsummer soup is the best in memory, and he gets the first bowl.", "vars": {"herb": ["thyme", "rosemary", "lovage", "sage"], "cheese": ["crumbly goat cheese", "smoked cheese", "soft white cheese"]}},
  {"id": "v-dyes-for-banner", "style": "expedition", "title": "Seven Colors for the Banner", "hook": "The festival banner needs seven dyes, and each one hides somewhere in {village}.", "twist": "The seventh color isn’t a plant at all; it’s the dye made by everyone’s hands together.", "open": "The banner for the {festival} hangs white and waiting in {place}, and the weaver gives you seven little clay pots to fill.", "steps": ["The {berries} from the churchyard hedge give a deep purple, and your fingers turn it too.", "The miller lends onion skins for gold and the tanner offers oak bark for brown.", "At the pond, the reeds’ roots make a soft green, and {critter} watches disapprovingly.", "The weaver’s recipe book says blue comes from woad, which only grows by {landmark}.", "Past {landmark}, {helper} hands over a jar of red clay from the riverbank.", "Six pots are full, and the seventh holds only a note from the weaver: “the last color comes from the village.”"], "end": "Everyone presses one handprint on the banner in whatever color they like. The seventh color is all of them, and it flies over the {festival} proudly.", "vars": {"festival": ["autumn festival", "harvest fair", "midsummer fête", "lantern festival"], "berries": ["blackberries", "elderberries", "sloes", "bilberries"]}},
  {"id": "v-first-snowdrop-hunt", "style": "expedition", "title": "The Hunt for the First Snowdrop", "hook": "Spring can’t officially start in {village} until someone finds the first snowdrop, and this year you are the one looking.", "twist": "The first snowdrop has already opened, but it’s growing somewhere nobody thought to look.", "open": "The spring fair in {place} waits on tradition: the first snowdrop must be found, and the frost is still thick on the fields.", "steps": ["The churchyard, where snowdrops always begin, is still bare, but the ground feels softer by the south wall.", "{helper} says snowdrops grow where someone once planted them, and keeps a map of every bulb set.", "The map shows a ring of crosses around the schoolhouse, planted many winters ago.", "The schoolhouse garden is frozen solid, except for one warm spot by the {warm}.", "The children say the {warm} is where they sit at lunch to warm their hands.", "There, in a crack of the path, one white snowdrop is bowing its head in the gentle heat."], "end": "You bring {helper} and the children to see it, and the bell rings for spring. The fair opens with a snowdrop in every {buttonhole}.", "vars": {"warm": ["boiler vent", "kitchen chimney wall", "old stove pipe", "laundry vent"], "buttonhole": ["buttonhole", "hatband", "coat pocket", "schoolbag strap"]}},
  {"id": "v-teachers-treasure-hunt", "style": "expedition", "title": "The Schoolteacher’s Last Riddle", "hook": "The retired schoolteacher of {village} left a treasure hunt through town, and the first clue just turned up.", "twist": "The hunt was written for a class of children, now grown, who have forgotten they were in it.", "open": "A yellowed envelope has turned up in the library in {place}, addressed “To whoever is curious,” with a riddle about a bell.", "steps": ["The school bell’s rope hides a folded card: “Count the steps to where the {birds} sleep.”", "Forty steps from the school gate, the pond’s boathouse has a clue tacked to its door.", "{helper} remembers the teacher planning this hunt for her class of thirty years ago.", "Beneath the {statue} on the bank lie a key and the words “Now bring the others.”", "You gather the grown-up former students you can find, and each remembers a piece of the last riddle.", "Together they lead you to the old schoolroom, where the key opens a cupboard nobody has touched."], "end": "Inside is a box of letters the teacher wrote to each pupil, praising something they did. The whole class reads theirs together, and nobody leaves dry-eyed.", "vars": {"birds": ["swans", "ducks", "moorhens", "geese"], "statue": ["stone lion", "mossy sundial", "stone frog", "old milestone"]}},
  {"id": "v-wind-for-windmill", "style": "expedition", "title": "Finding Wind for the Mill", "hook": "The {village} windmill’s grand grinding day is here, but the wind needs to be persuaded to join.", "twist": "The wind has been waiting to be invited, the way the miller’s grandfather used to do it.", "open": "The miller in {place} has sacks of {grain} waiting and still sails, and the old invitation for the wind is lost.", "steps": ["The miller’s grandfather used to go door to door the morning before grinding day, but nobody remembers why.", "{helper} recalls a {ribbon} ribbon on every door and a tune the grandfather whistled.", "In the chapel records, the tune is written on the back of a hymn sheet, labeled “For the Wind.”", "The hill above the mill is the windiest spot in town, and its flagpole still has scraps of {ribbon} ribbon.", "Children tie fresh {ribbon} ribbons on every door while you learn the tune from the choir leader.", "At the top of the hill you whistle the old tune as loudly as you can, and the ribbons below start to stir."], "end": "The wind rolls down the hill, flicking every ribbon on its way, and the sails begin to turn. The {grain} is ground by nightfall, and the tradition is back.", "vars": {"grain": ["wheat", "barley", "rye", "oats"], "ribbon": ["blue", "yellow", "red", "white"]}},
  {"id": "v-verses-of-town-song", "style": "expedition", "title": "The Missing Verses", "hook": "The {village} town song has lost its verses, and each one was written into a different shop long ago.", "twist": "The final verse has never been written at all, and the town needs to finish it.", "open": "The town choir in {place} can only remember the first line of its own anthem, and founding day is this weekend.", "steps": ["{helper} says each shop was given one verse to keep when the town was founded.", "The bakery keeps its verse painted on the underside of the oldest bread board.", "The cobbler’s verse is stitched into the lining of {boots} that never sold.", "The apothecary finds hers on a label inside a jar of {sweets} older than her grandmother.", "The inn’s verse is carved into the bar, hidden behind a row of pewter tankards.", "The last shop, the new {newshop}, has no verse, because it didn’t exist when the town began."], "end": "You and the owner of the {newshop} write the final verse together, about everyone who arrived since. The choir sings it all on founding day, loudest at the end.", "vars": {"boots": ["a pair of red boots", "a pair of tall riding boots", "a pair of tiny baby boots"], "sweets": ["peppermints", "lemon drops", "horehound candies", "rose creams"], "newshop": ["bookshop", "tea room", "bicycle shop", "flower stall"]}},
  {"id": "v-lullabies-door-to-door", "style": "expedition", "title": "A Lullaby From Every House", "hook": "The new midwife wants a book of lullabies, and every house in {village} knows a different one.", "twist": "One house doesn’t know a lullaby, and it’s the one that needs one most.", "open": "The midwife in {place} gives you a {notebook} and a pencil, and asks for one lullaby from every door.", "steps": ["The baker sings a song about bread rising, and the flour on her apron puffs with every line.", "The blacksmith rumbles one in time to his hammer, very softly, so it’s almost a purr.", "A family by the pond shares a lullaby in their old language and draws the words out slowly for you.", "{helper} sings you three, then asks for the {notebook} back to add a fourth just remembered.", "One door, the house of new parents, has no song, only a baby who won’t sleep.", "The tired father says neither of them grew up with lullabies and they don’t know where to start."], "end": "You open the {notebook} on their kitchen table and sing them the first song. By the {page} page the baby is asleep, and the book stays at their house a while.", "vars": {"notebook": ["blank notebook", "cloth-bound songbook", "little green journal"], "page": ["tenth", "fourth", "seventh", "twelfth"]}},
  {"id": "v-wood-for-a-fiddle", "style": "expedition", "title": "Wood for a New Fiddle", "hook": "The {village} fiddle has cracked, and the luthier needs the right wood from the right places to make a new one.", "twist": "The right wood was never from a tree; it’s from something the village already loves.", "open": "The only fiddle in {place} has split down its back, and the luthier needs {top_wood}, {back_wood}, and “wood that remembers music.”", "steps": ["The {top_wood} comes from the hill above the church, a fallen branch still smelling of resin.", "The {back_wood} comes from the orchard, where a storm snapped off a limb last winter.", "The luthier holds up both pieces and says they’re fine, but they don’t remember any music.", "The old dance hall is being renovated, and its floorboards are piled near {landmark} for firewood.", "{helper} says three generations danced on those boards every Saturday night.", "You bring one board to the luthier, and when she taps it, it rings like a note."], "end": "The new fiddle has a back made from dance hall floor, and it plays the old {tunes} on the first try. The whole village dances in the square.", "vars": {"top_wood": ["spruce", "pine", "cedar"], "back_wood": ["maple", "pear wood", "cherry wood", "walnut"], "tunes": ["reels", "waltzes", "jigs", "hornpipes"]}}
];
